class Reader:
    """Reading mode: one long text field across the whole card, read in pages.

    The text is copied into a widget of its own; typing marks the record dirty,
    and sync() writes it back into the card's field before any save, so saving,
    autosaving and switching records behave exactly as in the card."""

    def __init__(self, app):
        self.app = app
        self.source = None          # the card's Text being read
        self.rid = None             # record it belongs to
        self.starts = None          # display line each page starts on; None = measure again
        self.hits, self.hit_i = [], -1
        f = self.frame = tk.Frame(app.cardbox, bg=PAPER)
        head = tk.Frame(f, bg=PAPER)
        head.pack(fill="x", padx=22, pady=(10, 4))
        # the controls are packed before the title, so a long title is what gets cut
        self.title = tk.Label(head, text="", bg=PAPER, fg=STAMP, font=app.f_label, anchor="w")
        ttk.Button(head, text=tr("close (Esc)"), style="Quiet.TButton",
                   command=self.close).pack(side="right", padx=(8, 0))
        ttk.Button(head, text=tr("find"), style="Quiet.TButton",
                   command=self.find_open).pack(side="right", padx=(8, 0))
        ttk.Button(head, text="›", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(1)).pack(side="right")
        self.page = tk.Label(head, text="", bg=PAPER, fg=SOFT, font=app.f_meta)
        self.page.pack(side="right", padx=6)
        ttk.Button(head, text="‹", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(-1)).pack(side="right")
        self.title.pack(side="left", fill="x", expand=True)
        self.findrow = tk.Frame(f, bg=PAPER)
        self.q = tk.StringVar()
        self.e_find = tk.Entry(self.findrow, textvariable=self.q, font=app.f_meta, bg=PAPER,
                               fg=INK, insertbackground=INK, relief="flat", highlightthickness=1,
                               highlightbackground=RULE, highlightcolor=STAMP)
        self.e_find.pack(side="left", fill="x", expand=True, ipady=2)
        self.found = tk.Label(self.findrow, text="", bg=PAPER, fg=OXIDE, font=app.f_meta)
        self.found.pack(side="left", padx=10)
        self.rule = tk.Frame(f, bg=STAMP, height=2)
        self.rule.pack(fill="x", padx=22)
        t = self.t = tk.Text(f, wrap="word", font=app.f_body, bg=PAPER, fg=INK, relief="flat",
                             insertbackground=INK, highlightthickness=0, padx=22, pady=12,
                             spacing1=2, spacing3=6, undo=True, autoseparators=True, maxundo=-1)
        t.pack(fill="both", expand=True)
        t.tag_configure("hit", background=RULE)
        t.tag_configure("cur", background=SELBG, foreground=SELFG)
        app.bind_undo(t, text=True)
        for seq, fn in (("<Prior>", lambda e: self.turn(-1)), ("<Next>", lambda e: self.turn(1)),
                        ("<Escape>", lambda e: self.close()), ("<Control-e>", lambda e: self.close()),
                        ("<Control-f>", lambda e: self.find_open())):
            t.bind(seq, fn)
        t.bind("<MouseWheel>", lambda e: self.turn(-1 if e.delta > 0 else 1))
        t.bind("<Button-4>", lambda e: self.turn(-1))
        t.bind("<Button-5>", lambda e: self.turn(1))
        t.bind("<KeyRelease>", self.typed, add="+")
        t.bind("<Configure>", self.resized)
        self.measure = tkfont.Font(font=app.f_body).measure("0") * 92   # ~92 characters a line
        self.q.trace_add("write", lambda *_: self.find_update())
        self.e_find.bind("<Return>", lambda e: self.next_hit(1))
        self.e_find.bind("<Shift-Return>", lambda e: self.next_hit(-1))
        self.e_find.bind("<Escape>", lambda e: self.find_close())
        self.e_find.bind("<Prior>", lambda e: self.turn(-1))
        self.e_find.bind("<Next>", lambda e: self.turn(1))

    @property
    def is_open(self):
        return self.source is not None

    def resized(self, event):
        """Keeps the text column at a readable width: in a wide window the
        margins grow instead of the lines."""
        pad = max(22, (event.width - self.measure) // 2)
        if int(self.t.cget("padx")) != pad:
            self.t.configure(padx=pad)
        self.starts = None
        self.app.root.after_idle(self.show_page)

    def open(self, source, title):
        if str(source.cget("state")) == "disabled":
            self.app.say(tr("Open a record first."))
            return
        rec = self.app.current()
        self.source, self.rid = source, self.app.sel
        self.title.configure(text=f"{title}  ·  {one_liner(label_any(rec, self.app.data), 60)}"
                             if rec else title)
        self.t.delete("1.0", "end")
        self.t.insert("1.0", source.get("1.0", "end-1c"))
        self.t.edit_reset()
        self.t.mark_set("insert", "1.0")
        self.starts = None
        self.find_close()
        self.frame.place(x=0, y=0, relwidth=1, relheight=1)
        self.frame.lift()
        self.t.focus_set()
        self.t.yview_moveto(0)
        self.app.root.after_idle(self.show_page)

    def typed(self, event):
        if event.keysym not in ("Prior", "Next", "Escape") and not event.keysym.startswith(
                ("Control", "Shift", "Alt")):
            self.app.mark_dirty()
            self.starts = None

    def sync(self):
        """Writes the reader's text back into the card's field, if it changed."""
        if not self.is_open:
            return
        text = self.t.get("1.0", "end-1c")
        if text != self.source.get("1.0", "end-1c"):
            self.source.delete("1.0", "end")
            self.source.insert("1.0", text)
            self.app.mark_dirty()

    def close(self, keep=True):
        if not self.is_open:
            return "break"
        if keep:
            self.sync()
        src = self.source
        self.source = self.rid = None
        self.frame.place_forget()
        try:
            src.focus_set()
            self.app.refit_card()
        except tk.TclError:
            pass
        return "break"

    # ---- pages: where each page starts is measured on screen, page by page
    def lines(self, a, b):
        n = self.t.count(a, b, "displaylines")
        return (n[0] if isinstance(n, tuple) else n) or 0

    def go_line(self, line):
        self.t.yview("1.0")
        if line > 0:
            self.t.yview_scroll(line, "units")
        self.t.update_idletasks()      # Tk applies the scroll lazily; settle it before reading "@0,0"

    def paginate(self):
        """The display line each page starts on. How many lines fit depends on
        how many paragraph gaps fall on the page, so each page is measured on
        screen where it falls: no line skipped, at most one repeated. Tk's
        `sync` lays the whole text out first, so the first measurement is not
        taken before the text has been laid out."""
        t = self.t
        if not t.winfo_ismapped() or t.winfo_height() < 40:
            self.starts = [0]                   # not on screen yet: measure on the next call
            return False
        t.tk.call(t._w, "sync")
        t.update_idletasks()
        keep = self.lines("1.0", "@0,0")
        h = t.winfo_height()
        total = self.lines("1.0", "end")
        starts = [0]
        while len(starts) < 5000:
            self.go_line(starts[-1])
            if t.yview()[1] >= 1.0:             # the end is on screen: last page
                break
            fit = max(1, self.lines("@0,0", f"@0,{h - 1}"))
            nxt = starts[-1] + fit
            if nxt >= total:
                break
            starts.append(nxt)
        self.starts = starts
        self.go_line(keep)
        return True

    def page_of(self, line):
        starts = self.starts or [0]
        i = 0
        while i + 1 < len(starts) and starts[i + 1] <= line:
            i += 1
        return i

    def current_page(self):
        if self.t.yview()[1] >= 1.0:
            return len(self.starts) - 1
        return self.page_of(self.lines("1.0", "@0,0"))

    def turn(self, delta):
        if not self.is_open:
            return "break"
        if self.starts is None:
            self.paginate()
        page = max(0, min(self.current_page() + delta, len(self.starts) - 1))
        self.go_line(self.starts[page])
        self.t.mark_set("insert", "@0,0")
        self.show_page()
        return "break"

    def show_page(self):
        if not self.is_open:
            return
        if self.starts is None and not self.paginate():
            self.starts = None
            self.app.root.after(60, self.show_page)
            return
        self.page.configure(text=tr("page {p} of {n}", p=self.current_page() + 1,
                                    n=len(self.starts)))

    # ---- find inside the text
    def find_open(self):
        self.findrow.pack(fill="x", padx=22, pady=(0, 6), before=self.rule)
        self.starts = None                     # the text area just got shorter
        self.e_find.focus_set()
        self.e_find.select_range(0, "end")
        return "break"

    def find_close(self):
        self.t.tag_remove("hit", "1.0", "end")
        self.t.tag_remove("cur", "1.0", "end")
        self.hits, self.hit_i = [], -1
        self.found.configure(text="")
        self.findrow.pack_forget()
        self.starts = None
        if self.is_open:
            self.t.focus_set()
        return "break"

    def find_update(self):
        t = self.t
        t.tag_remove("hit", "1.0", "end")
        t.tag_remove("cur", "1.0", "end")
        self.hits, self.hit_i = [], -1
        q = self.q.get()
        if q:
            idx = "1.0"
            while True:
                pos = t.search(q, idx, nocase=True, stopindex="end")
                if not pos:
                    break
                end = f"{pos}+{len(q)}c"
                t.tag_add("hit", pos, end)
                self.hits.append((pos, end))
                idx = end
        if not q:
            self.found.configure(text="")
        elif not self.hits:
            self.found.configure(text=tr("not found"))
        else:
            self.next_hit(1)

    def next_hit(self, delta):
        if not self.hits:
            return "break"
        self.hit_i = (self.hit_i + delta) % len(self.hits)
        pos, end = self.hits[self.hit_i]
        self.t.tag_remove("cur", "1.0", "end")
        self.t.tag_add("cur", pos, end)
        if self.starts is None:
            self.paginate()
        self.go_line(self.starts[self.page_of(self.lines("1.0", pos))])   # the page holding the match
        self.t.mark_set("insert", pos)
        self.found.configure(text=f"{self.hit_i + 1}/{len(self.hits)}")
        self.show_page()
        return "break"


# ================================================================ window

class App:
    def __init__(self, root, theme, notices):
        self.root = root
        self.theme = theme
        self.restart_theme = None
        self.data = load_json()
        self.sel = None
        self.scope = None          # None | "people" | "entries"
        self.tag = self.viewmode = self.date = None           # people filters
        self.view_circle = None                               # people filter: a circle, or "none"
        self.scope_explicit = False     # scope picked in COLLECTIONS (not implied by a filter)
        self.view_kind = self.view_lang = self.view_domain = None  # verba filters
        self.view_stype = None                                # source filter
        self.view_system = None                               # corpus filter
        self.view_htype = None                                # corpus type filter
        self.source_hints = []
        self.read_titles = {}       # Text widget -> its title, for reading mode
        self.draft = None
        self.dirty = False
        self.loading = False
        self.busy = False
        self.undo_resets = []
        self.carets = []
        self.pendings = []
        self.fits = []
        self.shown = None
        self.mode = "register"     # "register" (number order) | "index" (search)
        self.top = None            # first row of the view; None = the end (the newest)
        self.rows = 0              # how many rows fit in the list right now
        self.page_sig = None       # did the filter change? then the view goes back to the start
        self._fit_job = None
        ui = self.data.get("ui") or {}
        self.max_rows = int(ui.get("max_rows") or 10)
        self.locked_panes = bool(ui.get("panes_locked"))
        self.locked_var = tk.BooleanVar(value=self.locked_panes)

        serif = self.pick(["Times New Roman", "Liberation Serif",
                           "DejaVu Serif", "Georgia"], "Times")
        mono = self.pick(["Consolas", "Cascadia Mono", "Lucida Console",
                          "DejaVu Sans Mono", "Courier New"], "Courier")
        wanted = ui.get("font_mono")
        self.font_warning = ""
        if wanted:
            ok, why = self.usable_mono(wanted)
            if ok:
                mono = wanted
            else:
                self.font_warning = tr('Typeface "{name}" {why}; using {mono}.',
                                       name=wanted, why=why, mono=mono)
        body = mono if PAL["mono_only"] else serif
        self.f_name = (body, 15 if PAL["mono_only"] else 17)
        self.f_body = (body, 11)
        self.f_row = (body, 11)
        self.f_meta = (mono, 9)
        self.f_label = (mono, 8)

        root.title("Index")
        sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
        w, h = min(1180, sw - 80), min(740, sh - 120)
        root.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+{max(0, (sh - h) // 3)}")
        root.minsize(760, 470)
        root.configure(bg=SHELL)

        st = ttk.Style(root)
        st.theme_use("clam")
        st.configure("TFrame", background=SHELL)
        self.row_h = 24
        st.configure("Treeview", background=SHELL, fieldbackground=SHELL,
                     foreground=INK, borderwidth=0, rowheight=self.row_h, font=self.f_row)
        st.map("Treeview", background=[("selected", SELBG)],
               foreground=[("selected", SELFG)])
        st.configure("TScrollbar", background=RULE, troughcolor=SHELL,
                     bordercolor=SHELL, arrowcolor=SOFT, borderwidth=0,
                     gripcount=0, relief="flat", arrowsize=11)
        st.map("TScrollbar", background=[("active", SOFT)])
        st.configure("Sash", gripcount=0, sashthickness=4, background=RULE,
                     bordercolor=RULE, lightcolor=RULE, darkcolor=RULE)
        st.configure("Tag.Treeview", font=self.f_meta, rowheight=19)
        st.configure("TButton", background=PAPER, foreground=STAMP,
                     font=self.f_meta, borderwidth=1, focuscolor=STAMP,
                     padding=(9, 3), bordercolor=RULE, lightcolor=RULE,
                     darkcolor=RULE, relief="solid")
        st.map("TButton", background=[("active", SELBG)])
        st.configure("Quiet.TButton", foreground=SOFT)

        self.build_bar()
        self.build_body()
        self.build_status()
        self.build_menu()
        self.bind_keys()
        self.reload()
        paint_frame(root)
        if notices:
            self.root.after(500, lambda: self.say(" · ".join(notices)))
        elif self.font_warning:
            self.root.after(600, lambda: self.say(self.font_warning))

    def pick(self, names, fallback):
        have = set(tkfont.families(self.root))
        for n in names:
            if n in have:
                return n
        return fallback

    # ------------------------------------------------------------ chrome
    def build_bar(self):
        bar = tk.Frame(self.root, bg=PAPER, highlightthickness=0)
        bar.pack(fill="x")
        tk.Frame(self.root, bg=RULE, height=1).pack(fill="x")
        tk.Label(bar, text="INDEX", bg=PAPER, fg=STAMP,
                 font=(self.f_meta[0], 10)).pack(side="left", padx=(14, 16), pady=9)
        self.q = tk.StringVar()
        self._q_job = None
        self.q.trace_add("write", lambda *_: self.refresh_list_soon())
        self.entry = tk.Entry(bar, textvariable=self.q, font=(self.f_body[0], 13),
                              bg=PAPER, fg=INK, relief="flat", insertbackground=INK,
                              highlightthickness=1, highlightbackground=RULE,
                              highlightcolor=STAMP)
        self.entry.pack(side="left", fill="x", expand=True, ipady=4)
        self.count = tk.Label(bar, text="", bg=PAPER, fg=OXIDE, font=self.f_meta)
        self.count.pack(side="left", padx=14)
        ttk.Button(bar, text=tr("quick entry"), command=self.quick_add
                   ).pack(side="right", padx=(4, 12))
        ttk.Button(bar, text=tr("+ health"), command=self.new_metric
                   ).pack(side="right", padx=(4, 0))
        ttk.Button(bar, text=tr("+ source"), command=self.new_source
                   ).pack(side="right", padx=(4, 0))
        ttk.Button(bar, text=tr("+ form"), command=lambda: self.new_entry("form")
                   ).pack(side="right", padx=(4, 0))
        ttk.Button(bar, text=tr("+ concept"), command=lambda: self.new_entry("concept")
                   ).pack(side="right", padx=(4, 0))
        ttk.Button(bar, text=tr("+ person"), command=self.new_person).pack(side="right")

    def build_body(self):
        # opaqueresize off: while the divider is dragged only a thin line moves,
        # and the columns are laid out once, on release, instead of at every pixel
        pw = tk.PanedWindow(self.root, orient="horizontal", opaqueresize=False,
                            sashwidth=4, sashrelief="flat", bd=0, bg=RULE,
                            showhandle=False)
        pw.pack(fill="both", expand=True)

        rail = tk.Frame(pw, bg=SHELL)
        self.rail = ttk.Treeview(rail, columns=("n",), show="tree",
                                 style="Tag.Treeview", selectmode="browse")
        self.rail.column("#0", width=168, stretch=True)
        self.rail.column("n", width=38, anchor="e", stretch=False)
        rsb = ttk.Scrollbar(rail, orient="vertical", command=self.rail.yview)
        self.rail.configure(yscrollcommand=rsb.set)
        rsb.pack(side="right", fill="y")
        self.rail.pack(fill="both", expand=True)
        self.rail.tag_configure("head", foreground=FAINT, font=self.f_label)
        self.rail.tag_configure("on", foreground=OXIDE)
        self.rail.tag_configure("late", foreground=OXIDE)
        self.rail.tag_configure("today", foreground=STAMP)
        self.rail.tag_configure("scope", foreground=STAMP)
        self.rail.tag_configure("zero", foreground=FAINT)
        self.rail.bind("<<TreeviewSelect>>", self.on_rail)
        pw.add(rail, stretch="never", minsize=120)
        self.rail_pane = rail
        self.wide = False

        mid = tk.Frame(pw, bg=SHELL)
        self.chips = tk.Frame(mid, bg=SHELL)       # the filters in force (refresh_chips)
        head = tk.Frame(mid, bg=SHELL)
        head.pack(fill="x")
        self.list_head = head
        self.page_lbl = tk.Label(head, text="", bg=SHELL, fg=STAMP, font=self.f_label,
                                 anchor="w")
        self.page_lbl.pack(side="left", fill="x", expand=True, padx=(8, 0))
        ttk.Button(head, text="›", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(1)).pack(side="right", padx=(2, 4), pady=3)
        ttk.Button(head, text="‹", width=2, style="Quiet.TButton",
                   command=lambda: self.turn(-1)).pack(side="right", pady=3)
        tk.Frame(mid, bg=RULE, height=1).pack(fill="x")
        self.list = ttk.Treeview(mid, columns=("sub", "loc"), show="tree",
                                 selectmode="browse")
        self.list.column("#0", width=215, stretch=True)
        self.list.column("sub", width=165, stretch=True)
        self.list.column("loc", width=96, anchor="e", stretch=False)
        self.list.pack(fill="both", expand=True)
        self.list.tag_configure("sub", foreground=FAINT, font=self.f_meta)
        self.list.tag_configure("cancel", foreground=FAINT, font=self.f_meta)
        self.list.bind("<<TreeviewSelect>>", self.on_pick)
        self.list.bind("<Button-3>", self.row_menu)
        # no scrolling: the list shows what fits, and the rest is the next page
        self.list.bind("<Configure>", self.fit_soon)
        self.list.bind("<MouseWheel>", lambda e: self.turn(-1 if e.delta > 0 else 1))
        self.list.bind("<Button-4>", lambda e: self.turn(-1))
        self.list.bind("<Button-5>", lambda e: self.turn(1))
        pw.add(mid, stretch="always", minsize=200)
        self.mid_pane = mid

        self.cardbox = tk.Frame(pw, bg=PAPER)
        self.locus = tk.Label(self.cardbox, text="", bg=PAPER, fg=FAINT,
                              font=self.f_label, anchor="w", padx=22)
        self.locus.pack(fill="x", pady=(8, 0))
        pw.add(self.cardbox, stretch="always", minsize=320)
        self.pw = pw
        self.apply_pane_lock()
        self.pc = PersonCard(self, self.cardbox)
        self.vc = EntryCard(self, self.cardbox)
        self.sc = SourceCard(self, self.cardbox)
        self.mc = MetricCard(self, self.cardbox)
        self.cards = {"person": self.pc, "entry": self.vc, "source": self.sc,
                      "metric": self.mc}
        self.reader = Reader(self)
        for card in self.cards.values():
            card.stamp.configure(cursor="hand2")
            card.stamp.bind("<Button-1>", lambda e: self.copy_id())
        self.locus.configure(cursor="hand2")
        self.locus.bind("<Button-1>", lambda e: self.copy_number())
        self.show_card("person")
        for c in self.cards.values():
            c.enable(False)
        self.laid_out = False
        pw.bind("<Configure>", self.first_layout)

    def show_card(self, kind):
        if self.shown == kind:
            return
        for c in self.cards.values():
            c.frame.pack_forget()
        self.cards[kind].frame.pack(fill="both", expand=True)
        self.shown = kind

    @property
    def card(self):
        return self.cards[self.shown or "person"]

    # ---- pieces shared by the cards
    def listbox(self, parent, pad):
        lb = tk.Listbox(parent, height=2, width=1, font=self.f_meta, bg=PAPER, fg=INK,
                        relief="flat", highlightthickness=0, selectbackground=SELBG,
                        selectforeground=SELFG, activestyle="none")
        lb.pack(fill="x", **pad)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        return lb

    def jump(self, lb, ids):
        sel = lb.curselection()
        if sel and sel[0] < len(ids):
            self.goto(ids[sel[0]])

    def textfield_bare(self, parent, rows, pad):
        t = tk.Text(parent, height=rows, width=1, font=self.f_meta, bg=PAPER, fg=INK,
                    relief="flat", wrap="word", insertbackground=INK,
                    highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                    undo=True, autoseparators=True, maxundo=-1)
        self.block_caret(t, self.f_meta)
        self.bind_undo(t, text=True)
        t.pack(fill="x", **pad)
        self.autogrow(t, minrows=rows)
        return t

    def source_field(self, parent, pad):
        """The SOURCE field shared by every card: takes a source's id (s_…) or
        free text. Below it, the resolved name and a button that opens it."""
        self.label(parent, tr("SOURCE  (a source's s_…, or free text)"), pad)
        row = tk.Frame(parent, bg=PAPER)
        row.pack(fill="x", **pad)
        e = tk.Entry(row, width=1, font=self.f_meta, bg=PAPER, fg=INK, relief="flat",
                     insertbackground=INK, highlightthickness=0,
                     disabledbackground=PAPER, disabledforeground=FAINT)
        e.pack(side="left", fill="x", expand=True)
        btn = ttk.Button(row, text=tr("open"), style="Quiet.TButton", width=6,
                         command=lambda: self.goto(e.get().strip()))
        btn.pack(side="right")
        hint = tk.Label(parent, text="", bg=PAPER, fg=SOFT, font=self.f_label, anchor="w")
        hint.pack(fill="x", **pad)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(2, 0), **pad)
        self.bind_undo(e)
        e.bind("<KeyRelease>", lambda ev: self.update_source_hint(e), add="+")
        self.source_hints.append((e, hint, btn))
        return e

    def update_source_hint(self, entry):
        for e, hint, btn in self.source_hints:
            if e is not entry:
                continue
            text = entry.get().strip()
            if text.startswith("s_"):
                s, shown = resolve_source(text, self.data)
                hint.configure(text=("→ " + shown) if s else shown,
                               fg=SOFT if s else OXIDE)
                btn.configure(state="normal" if s else "disabled")
            else:
                hint.configure(text=tr("free text (use + source to make it a record)")
                               if text else "", fg=FAINT)
                btn.configure(state="disabled")

    def flash(self, text):
        self.card.msg.configure(text=text)

    def first_layout(self, _event=None):
        if self.laid_out:
            return
        width = self.pw.winfo_width()
        if width < 200:
            return
        self.laid_out = True
        saved = (self.data.get("ui") or {}).get("panes")
        if saved and self.apply_panes(saved, width):
            return
        self.reset_layout()

    def apply_panes(self, saved, width):
        try:
            a, b = float(saved[0]), float(saved[1])
        except (TypeError, ValueError, IndexError):
            return False
        if not (0.05 < a < b < 0.95):
            return False
        try:
            self.set_sash(0, int(width * a))
            self.set_sash(1, int(width * b))
            return True
        except Exception:
            return False

    def set_sash(self, i, x):
        self.pw.sash_place(i, x, 0)

    def get_sash(self, i):
        return self.pw.sash_coord(i)[0]

    def save_prefs(self, patch):
        """Saves window preferences (ui.*) and takes back only those: the records
        loaded in the window keep their search text, drafts and the rest."""
        self.data["ui"] = save_ui(patch).get("ui", {})

    def remember_panes(self):
        if self.wide:
            return
        width = self.pw.winfo_width()
        if width < 200 or self.locked_panes:
            return
        try:
            a = self.get_sash(0) / width
            b = self.get_sash(1) / width
        except Exception:
            return
        if not (0.05 < a < b < 0.95):
            return
        self.save_prefs({"panes": [round(a, 4), round(b, 4)]})

    def toggle_wide(self):
        """F11 / Ctrl+Backslash: the card alone in the window, or back with the rail and list."""
        if self.wide:
            self.pw.add(self.mid_pane, before=self.cardbox, stretch="always", minsize=200)
            self.pw.add(self.rail_pane, before=self.mid_pane, stretch="never", minsize=120)
            self.wide = False

            def restore():
                saved = (self.data.get("ui") or {}).get("panes")
                if not (saved and self.apply_panes(saved, self.pw.winfo_width())):
                    self.reset_layout()
                self.refresh_list()
            self.root.after_idle(restore)
            self.say(tr("Rail and list back."))
        else:
            self.remember_panes()
            self.pw.forget(self.rail_pane)
            self.pw.forget(self.mid_pane)
            self.wide = True
            self.say(tr("Wide card. F11 brings the rail and the list back."))
        self.root.after_idle(self.refit_card)
        return "break"

    # ---- copying ids, numbers and citations, to paste into SOURCE and LINKS
    def copy_text(self, text):
        self.root.clipboard_clear()
        self.root.clipboard_append(text)
        self.say(tr("Copied: {value}", value=one_liner(text, 90)))

    def copy_id(self, rid=None):
        rid = rid or self.sel
        if not rid or rid.startswith("__"):
            self.say(tr("Save the record first: it gets its id on saving."))
            return "break"
        self.copy_text(rid)
        return "break"

    def copy_number(self, rid=None):
        rec = by_id(self.data).get(rid or self.sel or "")
        if rec and rec.get("reg_n"):
            self.copy_text(f"nº {rec['reg_n']}")
        return "break"

    def row_menu(self, event):
        """Right-click on a list row: copy its id, its number, or (sources) the
        citation, without opening it."""
        iid = self.list.identify_row(event.y)
        if not iid:
            return "break"
        m = self.menu(self.root)
        if iid.startswith("x:"):
            m.add_command(label=tr("Copy register number"),
                          command=lambda: self.copy_text(f"nº {iid[2:]}"))
        else:
            rec = by_id(self.data).get(iid)
            if not rec or iid.startswith("__"):
                return "break"
            m.add_command(label=tr("Copy id") + f"   {iid}", command=lambda: self.copy_id(iid))
            if rec.get("reg_n"):
                m.add_command(label=tr("Copy register number") + f"   nº {rec['reg_n']}",
                              command=lambda: self.copy_number(iid))
            if coll_of(iid) == "sources":
                m.add_command(label=tr("Copy ABNT citation"),
                              command=lambda: self.copy_text(cite(rec, "abnt", self.data)))
            m.add_command(label=tr("Copy as a link line") + f"   about {iid}",
                          command=lambda: self.copy_text(f"about {iid}"))
        try:
            m.tk_popup(event.x_root, event.y_root)
        finally:
            m.grab_release()
        return "break"

    def open_reader(self):
        """Ctrl+E: reading mode for the text field in focus, or the card's notes."""
        if self.reader.is_open:
            return self.reader.close()
        w = self.root.focus_get()
        if w in self.read_titles:
            self.reader.open(w, self.read_titles[w])
        elif self.sel:
            t = getattr(self.card, "t_notes", None)
            if t is not None:
                self.reader.open(t, self.read_titles.get(t, tr("NOTES")))
        return "break"

    def lock_panes(self):
        self.locked_panes = bool(self.locked_var.get())
        self.save_prefs({"panes_locked": self.locked_panes})
        self.apply_pane_lock()
        self.say(tr("Widths locked.") if self.locked_panes else tr("Widths free."))

    def apply_pane_lock(self):
        for seq in ("<Button-1>", "<B1-Motion>", "<ButtonRelease-1>"):
            if self.locked_panes:
                self.pw.bind(seq, lambda e: "break")
            else:
                self.pw.unbind(seq)
        if not self.locked_panes:
            # the class binding moves the sash after this one runs: read it afterwards
            self.pw.bind("<ButtonRelease-1>",
                         lambda e: self.root.after_idle(self.remember_panes), add="+")

    def reset_layout(self):
        width = max(self.pw.winfo_width(), 700)
        rail = max(150, min(210, int(width * 0.17)))
        listw = max(230, int(width * 0.30))
        try:
            self.set_sash(0, rail)
            self.set_sash(1, rail + listw)
        except Exception:
            pass

    def build_status(self):
        tk.Frame(self.root, bg=RULE, height=1).pack(fill="x")
        row = tk.Frame(self.root, bg=PAPER)
        row.pack(fill="x")
        self.status = tk.Label(row, text="", bg=PAPER, fg=SOFT, font=self.f_meta,
                               anchor="w")
        self.status.pack(side="left", padx=12, pady=4)
        tk.Label(row, text=f"{HOST}  ·  {BASE}", bg=PAPER, fg=FAINT,
                 font=self.f_meta).pack(side="right", padx=12)

    def menu(self, parent):
        return tk.Menu(parent, tearoff=0, bg=PAPER, fg=INK, activebackground=SELBG,
                       activeforeground=SELFG, borderwidth=1, font=self.f_meta)

    def build_menu(self):
        m = self.menu(self.root)
        f = self.menu(m)
        f.add_command(label=tr("New person"), accelerator="Ctrl+N", command=self.new_person)
        f.add_command(label=tr("New concept"), command=lambda: self.new_entry("concept"))
        f.add_command(label=tr("New form"), command=lambda: self.new_entry("form"))
        f.add_command(label=tr("New source"), command=self.new_source)
        f.add_command(label=tr("New health record (corpus)"), command=self.new_metric)
        f.add_command(label=tr("Quick entry…"), accelerator="Ctrl+Q", command=self.quick_add)
        f.add_separator()
        f.add_command(label=tr("Save"), accelerator="Ctrl+S", command=self.save)
        f.add_command(label=tr("Reload from disk"), accelerator="F5", command=self.reload)
        f.add_separator()
        f.add_command(label=tr("Quit"), command=self.on_close)
        m.add_cascade(label=tr("File"), menu=f)

        b = self.menu(m)
        b.add_command(label=tr("Rebuild markdown mirror"), command=self.do_mirror)
        b.add_command(label=tr("Open body map (corpus, HTML)"), command=self.do_corpus)
        b.add_command(label=tr("Health report (corpus, HTML)"), command=self.do_health)
        b.add_command(label=tr("Check structure"), command=self.do_doctor)
        b.add_command(label=tr("Normalize inline #tags (people)"), command=self.do_normalize)
        b.add_separator()
        b.add_command(label=tr("Merge sync conflicts"), command=self.do_merge)
        b.add_command(label=tr("History of the open record"), command=self.do_history)
        b.add_separator()
        b.add_command(label=tr("Import sources from Zotero (CSL-JSON or BibTeX)…"),
                      command=self.do_import_zotero)
        b.add_command(label=tr("Export sources (BibTeX)"), command=lambda: self.do_export("bibtex"))
        b.add_command(label=tr("Export sources (CSL-JSON)"), command=lambda: self.do_export("csl"))
        b.add_command(label=tr("Export sources (ABNT, text)"), command=lambda: self.do_export("abnt"))
        m.add_cascade(label=tr("Base"), menu=b)

        v = self.menu(m)
        v.add_command(label=tr("Terminal typeface…"), command=self.choose_typeface)
        v.add_command(label=tr("Entry card fields…"), command=self.card_layout_dialog)
        v.add_command(label=tr("Open as logbook"), accelerator="Ctrl+B", command=self.open_book)
        v.add_command(label=tr("Wide card"), accelerator="F11", command=self.toggle_wide)
        v.add_command(label=tr("Read field"), accelerator="Ctrl+E", command=self.open_reader)
        v.add_separator()
        v.add_command(label=tr("Reset widths"), command=self.reset_layout)
        v.add_checkbutton(label=tr("Lock widths"), onvalue=True, offvalue=False,
                          variable=self.locked_var, command=self.lock_panes)
        v.add_separator()
        for key, spec in THEMES.items():
            v.add_command(label=("• " if key == self.theme else "   ") + spec["label"],
                          command=lambda k=key: self.switch_theme(k))
        v.add_separator()
        lang = self.menu(v)
        for code, name in LANGS.items():
            lang.add_command(label=("• " if code == LANG else "   ") + name,
                             command=lambda c=code: self.switch_language(c))
        v.add_cascade(label=tr("Language"), menu=lang)
        m.add_cascade(label=tr("View"), menu=v)

        h = self.menu(m)
        h.add_command(label=tr("Shortcuts"), command=self.do_help)
        m.add_cascade(label=tr("Help"), menu=h)
        self.root.config(menu=m)

    def bind_keys(self):
        r = self.root
        r.bind("<Control-f>", lambda e: (self.entry.focus_set(),
                                         self.entry.select_range(0, "end")))
        r.bind("<Control-s>", lambda e: self.save())
        r.bind("<Control-n>", lambda e: self.new_person())
        r.bind("<Control-q>", lambda e: self.quick_add())
        r.bind("<Control-Return>", lambda e: self.save_and_new())
        r.bind("<F5>", lambda e: self.reload())
        r.bind("<Escape>", lambda e: self.list.focus_set())
        r.bind("<Control-j>", lambda e: self.step_record(1))
        r.bind("<Control-k>", lambda e: self.step_record(-1))
        r.bind("<Control-g>", lambda e: self.goto_dialog())
        r.bind("<Control-Key-0>", lambda e: self.set_scope(None))
        for n, key in enumerate(("people", "entries", "sources", "corpus"), 1):
            r.bind(f"<Control-Key-{n}>", lambda e, k=key: self.set_scope(k))
        self.entry.bind("<Down>", lambda e: self.focus_list())
        self.entry.bind("<Return>", lambda e: self.focus_list())
        self.list.bind("<slash>", lambda e: (self.entry.focus_set(),
                                             self.entry.select_range(0, "end"), "break")[2])
        self.list.bind("<Return>", lambda e: self.focus_card())
        self.list.bind("<Home>", lambda e: self.jump_list(0))
        self.list.bind("<End>", lambda e: self.jump_list(-1))
        self.list.bind("<Prior>", lambda e: self.turn(-1))
        self.list.bind("<Next>", lambda e: self.turn(1))
        r.bind("<Control-Prior>", lambda e: self.turn(-1))
        r.bind("<Control-Next>", lambda e: self.turn(1))
        r.bind("<Control-l>", lambda e: self.to_register())
        r.bind("<Control-b>", lambda e: self.open_book())
        r.bind("<F11>", lambda e: self.toggle_wide())
        r.bind("<Control-backslash>", lambda e: self.toggle_wide())
        r.bind("<Control-e>", lambda e: self.open_reader())
        r.bind("<Control-C>", lambda e: self.copy_id())        # Ctrl+Shift+C
        self.list.bind("<Control-Home>", lambda e: self.turn_to(0))
        self.list.bind("<Control-End>", lambda e: self.turn_to(None))
        self.list.bind("<Down>", lambda e: self.edge_step(1, e))
        self.list.bind("<Up>", lambda e: self.edge_step(-1, e))

    def jump_list(self, i):
        kids = self.list.get_children()
        if kids:
            self.list.selection_set(kids[i])
            self.list.see(kids[i])
        return "break"

    def focus_card(self):
        if self.sel:
            self.card.e_name.focus_set()
        return "break"

    def step_record(self, delta):
        """Ctrl+J / Ctrl+K: next / previous in the list, from anywhere."""
        kids = self.list.get_children()
        if not kids:
            return "break"
        cur = self.list.selection()
        cur = cur[0] if cur else self.sel
        if cur in kids:
            i = kids.index(cur) + delta
        else:
            i = 0 if delta > 0 else len(kids) - 1
        if not 0 <= i < len(kids):
            # past the edge: turn the page
            before = self.top
            self.turn(delta)
            if self.top == before:
                return "break"
            kids = self.list.get_children()
            if not kids:
                return "break"
            i = 0 if delta > 0 else len(kids) - 1
        self.list.selection_set(kids[i])
        self.list.see(kids[i])
        return "break"

    def edge_step(self, delta, _event=None):
        """Down arrow on the last row (or up on the first) turns the page
        instead of doing nothing."""
        kids = self.list.get_children()
        cur = self.list.focus()
        if kids and cur in (kids[-1] if delta > 0 else kids[0],):
            return self.step_record(delta)
        return None

    def turn(self, delta):
        """Turns a page: as many rows as fit in the list."""
        rows = max(1, self.rows or self.rows_fit())
        top = (self.top or 0) + delta * rows
        if top >= len(self.view) or (delta < 0 and (self.top or 0) == 0):
            return "break"            # already on the last (or the first) page
        self.top = max(0, top)
        self.refresh_list()
        kids = self.list.get_children()
        if kids:
            self.list.focus(kids[0] if delta >= 0 else kids[-1])
        return "break"

    def turn_to(self, top):
        """Ctrl+Home / Ctrl+End: start or end of the list."""
        self.top = top
        self.refresh_list()
        return "break"

    def rows_fit(self):
        h = self.list.winfo_height()
        if h < 40:              # not drawn yet
            return 20
        return max(1, (h - 4) // self.row_h)

    def fit_soon(self, _event=None):
        """The window changed size: redraw once it stops changing."""
        if self._fit_job:
            try:
                self.root.after_cancel(self._fit_job)
            except tk.TclError:
                pass
        self._fit_job = self.root.after(90, self.fit)

    def fit(self):
        self._fit_job = None
        if self.rows_fit() != self.rows:
            self.refresh_list()

    def open_book(self):
        """Ctrl+B: the base as a logbook, in a second window, open on the
        current record's page. Read-only; Enter in the logbook brings a record here."""
        self.commit_if_dirty()
        rec = self.current()
        win = tk.Toplevel(self.root)
        win.book = BookView(win, self.data, start_id=(rec or {}).get("id"),
                            on_open=self.open_from_book)
        return "break"

    def open_from_book(self, rid):
        if rid not in by_id(self.data):
            self.say(tr("{id} no longer exists (the logbook shows the base as it was "
                        "when opened).", id=rid))
            return
        self.goto(rid)
        self.root.lift()
        self.root.focus_force()

    def to_register(self, n=None):
        """Ctrl+L: leaves the search and the filters and shows the open record
        (or the requested nº) in its place in the sequence."""
        self.commit_if_dirty()
        rec = self.current()
        self.clear_filters()
        self.scope = None
        self.q.set("")
        if self._q_job:          # the empty search is drawn right now instead
            try:
                self.root.after_cancel(self._q_job)
            except tk.TclError:
                pass
            self._q_job = None
        self.refresh_rail()
        self.refresh_list()
        target = n or (rec or {}).get("reg_n")
        if target:
            self.show_number(target)
        self.list.focus_set()
        return "break"

    def show_number(self, n):
        """Moves the view to nº n (mid-page, if possible)."""
        i = self.view_num.get(n)
        if i is None:
            return
        kids = self.list.get_children()
        iid = self.view[i][1].get("id") if self.view[i][0] == "r" else f"x:{n}"
        if iid not in kids:
            self.top = max(0, i - self.rows // 2)
            self.refresh_list()

    def set_scope(self, key):
        self.commit_if_dirty()
        self.clear_filters()
        self.scope = key
        self.scope_explicit = key is not None
        self.refresh_rail()
        self.refresh_list()
        if key == "corpus" and (self.sel is None or self.rec_kind(self.current()) != "metric"):
            self.show_corpus_blank()
        return "break"

    def goto_dialog(self):
        """Ctrl+G: go to a record by number, stamp, id or name."""
        win = self.dialog(tr("Go to"), 520, 130)
        tk.Label(win, text=tr("GO TO  (nº, stamp, id or name)"), bg=PAPER,
                 fg=FAINT, font=self.f_label).pack(anchor="w", padx=18, pady=(14, 2))
        e = tk.Entry(win, font=self.f_body, bg=PAPER, fg=INK, insertbackground=INK,
                     relief="flat", highlightthickness=1, highlightbackground=RULE,
                     highlightcolor=STAMP)
        e.pack(fill="x", padx=18, ipady=3)

        def go(_ev=None):
            key = e.get().strip()
            win.destroy()
            if not key:
                return
            idx = by_id(self.data)
            if key in idx:
                self.goto(key)
                return
            m = re.fullmatch(r"(?i)\s*(?:n[ºo°.]?)?\s*(\d+)\s*", key)
            if m:
                r = find_by_reg(self.data, m.group(1))
                if r and r.get("id") in idx:
                    self.goto(r["id"])
                elif r:
                    self.to_register(r["reg_n"])
                    iid = f"x:{r['reg_n']}"
                    if self.list.exists(iid):
                        self.list.selection_set(iid)
                        self.list.see(iid)
                else:
                    self.say(tr("No record with nº or stamp {key}.", key=m.group(1)))
                return
            low = key.lower()
            hits = [r for r in idx.values() if r.get("name", "").lower() == low]
            if not hits:
                hits = [r for r in idx.values() if low in r.get("name", "").lower()]
            if len(hits) == 1:
                self.goto(hits[0]["id"])
            elif hits:
                self.q.set(key)
                self.say(tr("{n} records with that name; pick one in the list.", n=len(hits)))
            else:
                self.say(tr("Nothing called {key}.", key=key))

        e.bind("<Return>", go)
        win.bind("<Escape>", lambda ev: win.destroy())
        e.focus_set()
        return "break"

    # ------------------------------------------------------------ widgets
    def label(self, parent, text, pad):
        lbl = tk.Label(parent, text=text, bg=PAPER, fg=FAINT, font=self.f_label, anchor="w")
        lbl.pack(fill="x", pady=(6, 2), **pad)
        return lbl

    def readable(self, label, text, title):
        """A double-click on the field's title opens it in reading mode."""
        self.read_titles[text] = title
        label.configure(cursor="hand2")
        label.bind("<Double-Button-1>", lambda e: self.reader.open(text, title))

    def field(self, parent, text, font, pad):
        self.label(parent, text, pad)
        e = tk.Entry(parent, width=1, font=font, bg=PAPER, fg=INK, relief="flat",
                     insertbackground=INK, highlightthickness=0,
                     disabledbackground=PAPER, disabledforeground=FAINT)
        e.pack(fill="x", **pad)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        self.bind_undo(e)
        return e

    def textfield(self, parent, text, rows, font, pad):
        lbl = self.label(parent, text, pad)
        box = tk.Frame(parent, bg=PAPER)
        box.pack(fill="x", **pad)
        t = tk.Text(box, height=rows, width=1, font=font, bg=PAPER, fg=INK,
                    relief="flat", wrap="word", insertbackground=INK,
                    highlightthickness=0, padx=0, spacing1=1, spacing3=3,
                    undo=True, autoseparators=True, maxundo=-1)
        self.block_caret(t, font)
        self.bind_undo(t, text=True)
        t.pack(side="left", fill="both", expand=True)
        self.autogrow(t, minrows=rows)
        tk.Frame(parent, bg=RULE, height=1).pack(fill="x", pady=(4, 0), **pad)
        self.readable(lbl, t, text.split("  (")[0])
        return t

    def scroll_area(self, parent):
        """The whole card scrolls; the fields inside it do not."""
        canvas = tk.Canvas(parent, bg=PAPER, highlightthickness=0, bd=0)
        bar = ttk.Scrollbar(parent, orient="vertical", command=canvas.yview)
        inner = tk.Frame(canvas, bg=PAPER)
        win = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=bar.set)
        bar.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        pending = {"job": None}

        def apply_region():
            pending["job"] = None
            try:
                if canvas.winfo_exists():
                    canvas.configure(scrollregion=canvas.bbox("all"))
            except tk.TclError:
                pass

        def resized(_e=None):
            if pending["job"]:
                try:
                    canvas.after_cancel(pending["job"])
                except tk.TclError:
                    pass
            pending["job"] = canvas.after(45, apply_region)

        inner.bind("<Configure>", resized)
        canvas.bind("<Configure>", lambda e: canvas.itemconfigure(win, width=e.width))

        def wheel(e):
            if not canvas.winfo_exists():
                return
            step = 1 if (getattr(e, "num", 0) == 5 or e.delta < 0) else -1
            w = e.widget
            if isinstance(w, tk.Text):
                first, last_ = w.yview()
                if not (first <= 0.0 and last_ >= 1.0):
                    w.yview_scroll(step * 2, "units")
                    return
            canvas.yview_scroll(step * 3, "units")

        def claim(_e=None):
            for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                canvas.bind_all(seq, wheel)

        def release(_e=None):
            for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                canvas.unbind_all(seq)

        canvas.bind("<Enter>", claim)
        canvas.bind("<Leave>", release)
        self.canvases = getattr(self, "canvases", []) + [canvas]
        self.pendings.append((canvas, pending))
        return inner

    def autogrow(self, t, minrows=2):
        """As many rows as the text needs, measuring the wrap in the widget's own
        font (asking Tk does not work: it only counts up to the current height)."""
        last = {"n": None, "w": None, "job": None}
        CAP = self.max_rows

        def rows_needed():
            width = t.winfo_width()
            if width <= 1:
                return None
            if len(t.get("1.0", "end-1c")) > 3000:
                return None        # long text: counting lines is enough, and never hangs
            try:
                f = tkfont.Font(font=t.cget("font"))
            except tk.TclError:
                return None
            space = f.measure(" ")
            rows = 0
            for line in t.get("1.0", "end-1c").split("\n"):
                if not line:
                    rows += 1
                    continue
                used, n = 0, 1
                for word in line.split(" "):
                    w = f.measure(word)
                    if used and used + space + w > width:
                        n += 1
                        used = w
                    else:
                        used += (space if used else 0) + w
                rows += n
            return rows

        def fit(_e=None):
            if not t.winfo_exists():
                return
            n = rows_needed()
            if n is None:
                n = int(t.index("end-1c").split(".")[0])
            n = min(CAP, max(minrows, n))
            if n != last["n"]:
                last["n"] = n
                t.configure(height=n)
            if n < CAP:
                t.yview_moveto(0)

        def later(_e=None):
            if last["job"]:
                try:
                    t.after_cancel(last["job"])
                except tk.TclError:
                    pass
            last["job"] = t.after(45, fit)

        def on_configure(e):
            if e.width == last["w"]:
                return
            last["w"] = e.width
            later()

        t.bind("<KeyRelease>", later, add="+")
        t.bind("<Configure>", on_configure, add="+")
        for seq in ("<<Paste>>", "<<Cut>>", "<<Undo>>", "<<Redo>>"):
            t.bind(seq, later, add="+")
        self.fits.append((t, fit))
        self.pendings.append((t, last))
        return fit

    def refit_card(self):
        """Fits the fields and the scroll area of the card on screen only; the
        three hidden cards are fitted when they are shown."""
        shown = str(self.card.frame) + "."
        for t, fit in self.fits:
            if str(t).startswith(shown):
                fit()
        for canvas in getattr(self, "canvases", []):
            if str(canvas).startswith(shown) and canvas.winfo_exists():
                canvas.update_idletasks()
                canvas.configure(scrollregion=canvas.bbox("all"))
                canvas.yview_moveto(0)

    def bind_undo(self, widget, text=False):
        """Ctrl+Z / Ctrl+Y everywhere. Text has its own stack; Entry gets one."""
        if text:
            def undo(_e=None):
                try:
                    widget.edit_undo()
                except tk.TclError:
                    pass
                self.mark_dirty()
                return "break"

            def redo(_e=None):
                try:
                    widget.edit_redo()
                except tk.TclError:
                    pass
                self.mark_dirty()
                return "break"

            self.undo_resets.append(
                lambda w=widget: (w.edit_reset(), w.edit_modified(False)))
        else:
            import time as _time
            hist = {"stack": [""], "pos": 0, "when": 0.0}

            def commit():
                val = widget.get()
                if hist["stack"][hist["pos"]] == val:
                    return
                del hist["stack"][hist["pos"] + 1:]
                hist["stack"].append(val)
                hist["pos"] = len(hist["stack"]) - 1
                if len(hist["stack"]) > 200:
                    hist["stack"].pop(0)
                    hist["pos"] -= 1

            def snapshot(event=None):
                now = _time.monotonic()
                boundary = event is not None and getattr(
                    event, "char", "") in (" ", ",", ".", ";", ":", "-", "/")
                if boundary or now - hist["when"] > 0.7:
                    commit()
                hist["when"] = now

            def restore(val):
                widget.delete(0, "end")
                widget.insert(0, val)
                widget.icursor("end")

            def undo(_e=None):
                commit()
                if hist["pos"] > 0:
                    hist["pos"] -= 1
                    restore(hist["stack"][hist["pos"]])
                    self.mark_dirty()
                return "break"

            def redo(_e=None):
                if hist["pos"] < len(hist["stack"]) - 1:
                    hist["pos"] += 1
                    restore(hist["stack"][hist["pos"]])
                    self.mark_dirty()
                return "break"

            def reset(w=widget):
                hist["stack"] = [w.get()]
                hist["pos"] = 0
                hist["when"] = 0.0

            widget.bind("<KeyRelease>", snapshot, add="+")
            widget.bind("<<Paste>>", lambda e: widget.after(1, commit), add="+")
            self.undo_resets.append(reset)

        for seq in ("<Control-z>", "<Control-Z>"):
            widget.bind(seq, undo)
        for seq in ("<Control-y>", "<Control-Y>", "<Control-Shift-Z>",
                    "<Control-Shift-z>"):
            widget.bind(seq, redo)

    def char_width(self, font):
        try:
            return max(2, tkfont.Font(family=font[0], size=font[1]).measure("M"))
        except Exception:
            return 8

    def stop_carets(self):
        """Cancels every timer before the window is destroyed."""
        for t, state in self.carets + self.pendings:
            try:
                if state.get("job"):
                    t.after_cancel(state["job"])
                    state["job"] = None
            except Exception:
                pass
        self.carets = []

    def block_caret(self, t, font):
        """A block cursor, inverting the character under it."""
        cw = self.char_width(font)
        t.configure(insertwidth=0, insertbackground=INK)
        t.tag_configure("caret", background=INK, foreground=PAPER)
        try:
            t.tag_lower("caret", "sel")
        except tk.TclError:
            pass
        state = {"on": True, "job": None, "focus": False}

        def paint():
            if not t.winfo_exists():
                return
            t.tag_remove("caret", "1.0", "end")
            if not state["focus"] or not state["on"] or t.tag_ranges("sel"):
                t.configure(insertwidth=0)
                return
            i = t.index("insert")
            if t.compare(i, ">=", i.split(".")[0] + ".end"):
                t.configure(insertwidth=cw)
            else:
                t.configure(insertwidth=0)
                t.tag_add("caret", i, i + "+1c")

        def blink():
            if not t.winfo_exists():
                return
            state["on"] = not state["on"]
            paint()
            state["job"] = t.after(530, blink)

        def wake(_e=None):
            state["on"] = True
            paint()

        def gained(_e=None):
            state["focus"] = True
            wake()

        def lost(_e=None):
            state["focus"] = False
            paint()

        t.bind("<FocusIn>", gained, add="+")
        t.bind("<FocusOut>", lost, add="+")
        for ev in ("<KeyRelease>", "<ButtonRelease-1>", "<<Selection>>", "<B1-Motion>"):
            t.bind(ev, wake, add="+")
        state["job"] = t.after(530, blink)
        self.carets.append((t, state))
        paint()

    def usable_mono(self, family):
        try:
            if family not in tkfont.families(self.root):
                return False, tr("is not installed")
            f = tkfont.Font(family=family, size=11)
            widths = {f.measure(ch) for ch in "imMW1."}
            if len(widths) != 1:
                return False, tr("is not monospaced")
            if f.measure("M") < 3:
                return False, tr("has no metrics")
        except tk.TclError:
            return False, tr("is unreadable")
        return True, ""

    def mono_families(self):
        out = []
        for fam in sorted(set(tkfont.families(self.root))):
            if fam.startswith("@"):
                continue
            ok, _ = self.usable_mono(fam)
            if ok:
                out.append(fam)
        return out

    # ------------------------------------------------------------ dados
    def reload(self):
        """Reads the base again and rebuilds the search text of each record --
        only for records whose timestamp changed since the last time."""
        self.data = load_json()
        cache = getattr(self, "_hay", {})
        fresh = {}
        makers = (("people", lambda r: haystack_person(r)),
                  ("entries", lambda r: haystack_entry(r, self.data)),
                  ("sources", lambda r: haystack_source(r, self.data)),
                  ("corpus", lambda r: haystack_metric(r, self.data)))
        for coll, make in makers:
            for r in self.data[coll]:
                key = (r["id"], stamp_of(r))
                h = cache.get(key)
                if h is None:
                    h = make(r)
                r["_h"] = fresh[key] = h
        self._hay = fresh
        if self.draft:
            self.data[coll_of(self.draft["id"])].append(self.draft)
        self.refresh_rail()
        self.refresh_list()
        if getattr(self, "mc", None) and self.shown == "metric":
            self.mc.map.redraw()
        self.say(summary(self.data))

    def say(self, text):
        self.status.configure(text=text)

    def current(self):
        if not self.sel:
            return None
        return by_id(self.data).get(self.sel)

    def rec_kind(self, rec):
        return {"people": "person", "entries": "entry", "sources": "source",
                "corpus": "metric"}[coll_of((rec or {}).get("id", ""))]

    def refresh_list_soon(self):
        """The list redraws 150 ms after the last keystroke, not on every one."""
        if self._q_job:
            try:
                self.root.after_cancel(self._q_job)
            except tk.TclError:
                pass
        self._q_job = self.root.after(150, self.search_changed)

    def search_changed(self):
        self._q_job = None
        self.refresh_list()
        self.refresh_rail()

    def parse_query(self):
        """Search operators:
             p: v: f: c:      limit to a collection (people, verba, sources, corpus)
             ^text            only the start of the name
             tag:x lang:de type:book sys:renal dom:law id:c_measure
           The rest are literal terms, all required. type: and sys: match the
           stored key or its label in the current language."""
        q = self.q.get().strip().lower()
        scope, prefix, fields, terms = None, None, {}, []
        for tok in q.split():
            if tok in ("p:", "v:", "f:", "c:"):
                scope = {"p:": "people", "v:": "entries", "f:": "sources",
                         "c:": "corpus"}[tok]
            elif tok.startswith("^") and len(tok) > 1:
                prefix = tok[1:]
            elif ":" in tok and tok.split(":", 1)[0] in ("tag", "lang", "type", "sys",
                                                          "dom", "id") and tok.split(":", 1)[1]:
                k, v = tok.split(":", 1)
                fields[k] = v
            else:
                terms.append(tok)
        return scope, prefix, fields, terms

    def field_ok(self, r, fields):
        for k, v in fields.items():
            if k == "tag" and not any(v in t.lower() for t in r.get("tags", [])):
                return False
            if k == "lang" and (r.get("lang") or "").lower() != v:
                return False
            if k == "type" and not any(v in x.lower() for x in
                                       ((r.get("type") or ""), type_label(r.get("type")))):
                return False
            if k == "sys" and not any(v in x.lower() for x in
                                      ((r.get("system") or ""), system_label(r.get("system")))):
                return False
            if k == "dom" and not any(v in d.lower() for d in r.get("domains", [])):
                return False
            if k == "id" and not r.get("id", "").lower().startswith(v):
                return False
        return True

    def query_base(self):
        """What the search text alone finds, per collection: the words, ^prefix,
        field operators and p:/v:/f:/c:, but none of the rail's filters."""
        qscope, prefix, fields, terms = self.parse_query()

        def ok(r):
            if terms and not all(t in r.get("_h", "") for t in terms):
                return False
            if prefix and not sort_key(r.get("name", ""))[0].startswith(
                    sort_key(prefix)[0]):
                return False
            return self.field_ok(r, fields) if fields else True

        return {c: ([r for r in self.data[c] if ok(r)] if qscope in (None, c) else [])
                for c in COLLS}

    def matches(self):
        qscope = self.parse_query()[0]
        scope = qscope or self.scope
        base = self.query_base()
        out = []

        if scope in (None, "people"):
            for p in base["people"]:
                if self.tag and self.tag not in p.get("tags", []):
                    continue
                if self.viewmode in ("todo", "doing", "waiting") and \
                        not open_tasks(p, self.viewmode):
                    continue
                if self.viewmode == "untagged" and p.get("tags"):
                    continue
                if self.date and not any(t["due"] == self.date for t in dated_tasks(p)):
                    continue
                if self.view_circle == "none" and p.get("circles"):
                    continue
                if self.view_circle not in (None, "none") and \
                        self.view_circle not in p.get("circles", []):
                    continue
                out.append(p)
        if scope in (None, "entries"):
            for e in base["entries"]:
                if self.view_kind and e["kind"] != self.view_kind:
                    continue
                if self.view_lang and e.get("lang") != self.view_lang:
                    continue
                if self.view_domain and self.view_domain not in e.get("domains", []):
                    continue
                out.append(e)
        if scope in (None, "sources"):
            for s in base["sources"]:
                if self.view_stype and (s.get("type") or "outro") != self.view_stype:
                    continue
                out.append(s)
        if scope in (None, "corpus"):
            for m in base["corpus"]:
                if self.view_htype and htype(m) != self.view_htype:
                    continue
                if self.view_system is not None and (m.get("system") or "") != self.view_system:
                    continue
                out.append(m)
        out.sort(key=lambda r: sort_key(label_any(r, self.data) if coll_of(r["id"]) == "sources"
                                        else r["name"]))
        return out

    def row_text(self, r):
        """(title, subtitle) of a record in the list."""
        kind = self.rec_kind(r)
        if kind == "entry":
            sub = tr(r["kind"]) + " · " + (r.get("gloss") or "")
            return label_of(r), sub
        if kind == "source":
            au = author_names(r, self.data)
            sub = type_label(r.get("type") or "outro") + " · " + ", ".join(
                a.split(",")[0] for a in au[:2]) + (f" · {year_of_source(r)}"
                                                    if year_of_source(r) else "")
            return r.get("name") or r.get("raw", ""), sub
        if kind == "metric":
            t = htype(r)
            if t == "measure":
                lr = last_reading(r)
                sub = system_label(r.get("system") or "") + (
                    f" · {lr['date']} = {lr['value']} {r.get('unit', '')}" if lr
                    else " · " + tr("no readings"))
                if lr and out_of_range(r, lr):
                    sub += "  (!)"
            else:
                sub = tr(HEALTH_TYPE_LABEL[t]) + " · " + " · ".join(health_facts(r, self.data))
            return r["name"], sub
        p = r
        live = open_tasks(p)
        dated = sorted(dated_tasks(p), key=lambda t: due_label(t))
        if self.date:
            live = [t for t in dated if t["due"] == self.date] or live
        elif dated:
            live = dated + [t for t in live if t not in dated]
        if live:
            when = due_label(live[0])
            sub = "[{}] {}".format(MARK_OF.get(live[0].get("state"), " "),
                                   live[0].get("text", ""))
            if when:
                sub = when + "  " + sub
            if len(live) > 1:
                sub += f"  (+{len(live) - 1})"
        else:
            plain = [t for t in p.get("tags", []) if ":" not in t]
            sub = " · ".join(plain) or one_liner(p.get("notes_raw", ""), 70)
        return p["name"], sub

    def insert_row(self, r, loc):
        text, sub = self.row_text(r)
        self.list.insert("", "end", iid=r["id"], text=one_liner(text, 60),
                         values=(one_liner(sub, 60), loc), tags=("sub",))

    def filter_sig(self):
        return (self.q.get().strip(), self.scope, self.tag, self.viewmode, self.date,
                self.view_kind, self.view_lang, self.view_domain, self.view_stype,
                self.view_htype, self.view_circle, self.view_system)

    def refresh_list(self):
        """Without a search or filter, the list is the REGISTER: everything in
        number order, cancelled numbers in place, opening at the end (the newest).
        With a search or filter, it is the INDEX: what matches, alphabetically,
        each row with its number. Either way, the view only shows the rows that
        fit the window; the rest is on the following pages."""
        self._q_job = None
        sig = self.filter_sig()
        filtered = bool(any(sig[:-1]) or self.view_system is not None)
        if sig != self.page_sig:
            self.page_sig = sig
            self.top = 0 if filtered else None
        total = sum(len(self.data[c]) for c in COLLS)
        if filtered:
            self.mode = "index"
            self.view = [("r", r) for r in self.matches()]
        else:
            self.mode = "register"
            live, loose = {}, []
            for c in COLLS:
                for r in self.data[c]:
                    if r.get("reg_n"):
                        live[r["reg_n"]] = r
                    else:
                        loose.append(r)
            gone = {d["reg_n"]: d for d in self.data.get("deleted", [])
                    if d.get("reg_n") and d["reg_n"] not in live}
            self.view = [("r", live[n]) if n in live else ("x", gone[n])
                         for n in sorted(set(live) | set(gone))]
            self.view += [("r", r) for r in loose]       # drafts, at the end
        self.view_num = {o["reg_n"]: i for i, (_, o) in enumerate(self.view)
                         if o.get("reg_n")}
        self.view_pos = {o["id"]: i for i, (k, o) in enumerate(self.view) if k == "r"}
        self.rows = self.rows_fit()
        if self.top is None:          # the end: the last full view
            self.top = max(0, len(self.view) - self.rows)
        self.top = max(0, min(self.top, len(self.view) - 1))
        shown = self.view[self.top:self.top + self.rows]
        self.list.delete(*self.list.get_children())
        for kind, o in shown:
            n = o.get("reg_n")
            if kind == "x":
                self.list.insert("", "end", iid=f"x:{n}",
                                 text=tr("cancelled · {name}", name=one_liner(o.get("name", ""), 40)),
                                 values=(tr("on {date}", date=(o.get("at") or "")[:10]), f"nº {n}"),
                                 tags=("cancel",))
            else:
                self.insert_row(o, f"nº {n}" if n else tr("new"))
        a, b = self.top + 1, self.top + len(shown)
        if self.mode == "register":
            nums = [o.get("reg_n") for _, o in shown if o.get("reg_n")]
            span = f"nº {nums[0]}–{nums[-1]}" if nums else tr("empty")
            self.page_lbl.configure(text=tr("REGISTER · {span}", span=span))
            self.count.configure(text=tr("{n} records", n=total))
        else:
            self.page_lbl.configure(
                text=tr("INDEX · {a}–{b} of {n}", a=a, b=b, n=len(self.view)) if shown
                else tr("INDEX · nothing found"))
            self.count.configure(text=tr("{n} of {total}", n=len(self.view), total=total))
        if self.sel and self.list.exists(self.sel):
            self.list.selection_set(self.sel)
        self.refresh_chips()

    def show_in_list(self, rid):
        """Moves the view to the record, if it is outside it."""
        if self.list.exists(rid):
            return
        i = self.view_pos.get(rid)
        if i is None:
            if self.mode == "register":       # a new draft: it sits at the end
                self.top = None
                self.refresh_list()
            return
        self.top = max(0, i - self.rows // 2)
        self.refresh_list()

    def set_locus(self, rec):
        if not rec:
            self.locus.configure(text="")
            return
        n = rec.get("reg_n")
        if not n:
            self.locus.configure(text=tr("NOT REGISTERED · GETS A NUMBER ON SAVE"))
            return
        text = tr("REGISTER Nº {n}    REGISTERED {stamp}", n=n, stamp=stamp_label(rec.get("reg")))
        if rec.get("reg_origem"):
            text += "  " + tr("(inferred: {origin})", origin=tr(
                REG_ORIGIN.get(rec["reg_origem"], rec["reg_origem"])))
        if rec.get("reg_n_anterior"):
            text += "  · " + tr("formerly nº {n}", n=rec["reg_n_anterior"])
        self.locus.configure(text=text)

    def refresh_rail(self):
        """The rail lists every category of the base, always; its numbers count
        what the current search finds, so typing shows at once where the
        matches are (another collection, a tag, a language...). Categories with
        nothing for the search are dimmed, not hidden."""
        r = self.rail
        out = []                        # (iid, text, values, tags), applied at the end
        data = self.data
        base = self.query_base()
        people, entries, sources, corpus = (base[c] for c in COLLS)
        searching = bool(self.q.get().strip())

        def head(iid, text):
            out.append((iid, "", (), ("head",)))
            out.append((iid + "b", text, (), ("head",)))

        def item(iid, text, n, on, extra=()):
            tags = ("on",) if on else tuple(extra) + (("zero",) if searching and not n else ())
            out.append((iid, text, (n,), tags))

        out.append(("h0", tr("COLLECTIONS"), (), ("head",)))
        for coll, rows in zip(COLLS, (people, entries, sources, corpus)):
            item("s:" + coll, "  " + tr(COLL_LABEL[coll]), len(rows), self.scope == coll,
                 ("scope",))

        if data["people"]:
            head("h1", tr("WORK"))
            for key, lab in (("todo", tr("to do")), ("doing", tr("in progress")),
                             ("waiting", tr("waiting on"))):
                item("v:" + key, "  " + lab, sum(1 for p in people if open_tasks(p, key)),
                     self.viewmode == key)
            item("v:untagged", "  " + tr("untagged"),
                 sum(1 for p in people if not p.get("tags")), self.viewmode == "untagged")
            all_days = sorted({t["due"] for p in data["people"] for t in dated_tasks(p)})
            if all_days:
                days = {}
                for p in people:
                    for t in dated_tasks(p):
                        days[t["due"]] = days.get(t["due"], 0) + 1
                head("h3", tr("CALENDAR"))
                today = TODAY()
                for day in all_days:
                    mark, flag = ((("late",), "! ") if day < today else
                                  (("today",), "> ") if day == today else ((), "  "))
                    item("d:" + day, flag + day, days.get(day, 0), self.date == day, mark)
            # Covey's circles, outermost first; a person can be in more than one
            head("h2c", tr("CIRCLES"))
            for c in CIRCLES:
                item("o:" + c, "  " + tr(c), sum(1 for p in people if c in p.get("circles", [])),
                     self.view_circle == c)
            item("o:none", "  " + tr("no circle"),
                 sum(1 for p in people if not p.get("circles")), self.view_circle == "none")
            all_tags = sorted({t for p in data["people"] for t in p.get("tags", []) if ":" not in t},
                              key=sort_key)
            if all_tags:
                tags = {}
                for p in people:
                    for t in p.get("tags", []):
                        tags[t] = tags.get(t, 0) + 1
                head("h2", tr("TAGS"))
                for t in all_tags:
                    item("t:" + t, "  " + t, tags.get(t, 0), self.tag == t)

        if data["entries"]:
            head("h4", tr("KIND"))
            for key, lab in (("concept", tr("concepts")), ("form", tr("forms"))):
                item("k:" + key, "  " + lab, sum(1 for e in entries if e["kind"] == key),
                     self.view_kind == key)
            all_langs = sorted({e["lang"] for e in data["entries"]
                                if e["kind"] == "form" and e.get("lang")}, key=sort_key)
            if all_langs:
                head("h5", tr("LANGUAGE"))
                for lang in all_langs:
                    item("l:" + lang, "  " + lang,
                         sum(1 for e in entries if e["kind"] == "form" and e.get("lang") == lang),
                         self.view_lang == lang)
            all_doms = sorted({d for e in data["entries"] for d in e.get("domains", [])},
                              key=sort_key)
            if all_doms:
                head("h6", tr("DOMAIN"))
                for d in all_doms:
                    item("m:" + d, "  " + d, sum(1 for e in entries if d in e.get("domains", [])),
                         self.view_domain == d)

        if data["sources"]:
            head("h7", tr("SOURCE TYPE"))
            for t in sorted({s.get("type") or "outro" for s in data["sources"]},
                            key=lambda t: sort_key(type_label(t))):
                item("y:" + t, "  " + type_label(t),
                     sum(1 for s in sources if (s.get("type") or "outro") == t),
                     self.view_stype == t)
        if data["corpus"]:
            head("h9", tr("HEALTH"))
            present = {htype(m) for m in data["corpus"]}
            for t in HEALTH_TYPES:
                if t in present:
                    item("u:" + t, "  " + tr(HEALTH_TYPE_LABEL[t]),
                         sum(1 for m in corpus if htype(m) == t), self.view_htype == t)
            head("h8", tr("SYSTEM"))
            for sname in sorted({m.get("system") or "" for m in data["corpus"]},
                                key=lambda x: sort_key(system_label(x))):
                item("z:" + sname, "  " + (system_label(sname) or tr("(no system)")),
                     sum(1 for m in corpus if (m.get("system") or "") == sname),
                     self.view_system == sname)
        self.apply_rail(out)

    def apply_rail(self, rows):
        """Puts the rows on the rail. While typing the categories stay the same and
        only their numbers and dimming change, so the items are updated in place
        (a rebuild would redraw the whole rail and lose its scroll position)."""
        r = self.rail
        if tuple(r.get_children()) != tuple(iid for iid, *_ in rows):
            top = r.yview()[0]
            r.delete(*r.get_children())
            for iid, text, values, tags in rows:
                r.insert("", "end", iid=iid, text=text, values=values, tags=tags)
            r.yview_moveto(top)
            self._rail_rows = {iid: rest for iid, *rest in rows}
            return
        old = getattr(self, "_rail_rows", {})
        for iid, text, values, tags in rows:
            if old.get(iid) != [text, values, tags]:
                r.item(iid, text=text, values=values, tags=tags)
        self._rail_rows = {iid: [text, values, tags] for iid, text, values, tags in rows}

    # ---- the filters in force, shown as chips above the list
    FACETS = (("tag", "people"), ("viewmode", "people"), ("date", "people"),
              ("view_circle", "people"), ("view_kind", "entries"), ("view_lang", "entries"),
              ("view_domain", "entries"), ("view_stype", "sources"), ("view_htype", "corpus"),
              ("view_system", "corpus"))

    def facet_label(self, attr, value):
        if attr == "tag":
            return tr("tag: {tag}", tag=value)
        if attr == "viewmode":
            return {"todo": tr("to do"), "doing": tr("in progress"), "waiting": tr("waiting on"),
                    "untagged": tr("untagged")}.get(value, value)
        if attr == "view_circle":
            return tr("no circle") if value == "none" else tr(value)
        if attr == "view_kind":
            return tr("concepts") if value == "concept" else tr("forms")
        if attr == "view_stype":
            return type_label(value)
        if attr == "view_htype":
            return tr(HEALTH_TYPE_LABEL[value])
        if attr == "view_system":
            return system_label(value) or tr("(no system)")
        return value

    def drop_filter(self, attr):
        """Takes one filter away. A collection that only a filter had imposed
        (a tag implies people) goes with it; one picked in COLLECTIONS stays."""
        self.commit_if_dirty()
        if attr == "q":
            self.q.set("")
        elif attr == "scope":
            self.scope, self.scope_explicit = None, False
            self.clear_filters()
        elif attr == "all":
            self.q.set("")
            self.clear_filters()
            self.scope, self.scope_explicit = None, False
        else:
            setattr(self, attr, None)
            if not self.scope_explicit and all(getattr(self, a) is None for a, _ in self.FACETS):
                self.scope = None
        if self._q_job:
            try:
                self.root.after_cancel(self._q_job)
            except tk.TclError:
                pass
            self._q_job = None
        self.refresh_rail()
        self.refresh_list()

    def refresh_chips(self):
        """The bar of filters in force. Typing only changes the search chip's text,
        so the labels are kept and updated in place: rebuilding them (and packing
        the bar again) on every keystroke cost a full relayout of the list."""
        box = self.chips
        items = []
        q = self.q.get().strip()
        if q:
            items.append((tr("search: {q}", q=one_liner(q, 28)), "q"))
        if self.scope and self.scope_explicit:
            items.append((tr(COLL_LABEL[self.scope]), "scope"))
        for attr, _ in self.FACETS:
            value = getattr(self, attr)
            if value is not None and (value != "" or attr == "view_system"):
                items.append((self.facet_label(attr, value), attr))
        if len(items) > 1:
            items.append((tr("clear all"), "all"))
        shape = tuple(a for _, a in items)
        if shape != getattr(self, "_chip_shape", None):
            self._chip_shape = shape
            for w in box.winfo_children():
                w.destroy()
            for text, attr in items:
                lbl = tk.Label(box, bg=PAPER, fg=STAMP if attr != "all" else SOFT,
                               font=self.f_label, cursor="hand2", padx=6, pady=1,
                               highlightthickness=1, highlightbackground=RULE)
                lbl.pack(side="left", padx=(6, 0), pady=4)
                lbl.bind("<Button-1>", lambda e, a=attr: self.drop_filter(a))
            if items and not box.winfo_manager():
                box.pack(fill="x", before=self.list_head)
            elif not items and box.winfo_manager():
                box.pack_forget()
        for lbl, (text, attr) in zip(box.winfo_children(), items):
            text = ("× " if attr != "all" else "") + text
            if lbl.cget("text") != text:
                lbl.configure(text=text)

    def filter_system(self, sname):
        """A click on the map: filters the list by that system (again, removes the filter)."""
        self.commit_if_dirty()
        was = self.view_system
        self.clear_filters()
        self.view_system = None if was == sname else sname
        self.scope = "corpus"
        self.refresh_rail()
        self.refresh_list()
        if self.sel is None or self.rec_kind(self.current()) != "metric":
            self.show_corpus_blank()
        else:
            self.mc.map.set_current(self.view_system)

    def show_corpus_blank(self):
        """With no measurement open, the corpus card shows only the map."""
        self.blank_card()
        self.show_card("metric")
        self.mc.map.set_current(self.view_system)

    def clear_filters(self):
        self.tag = self.viewmode = self.date = self.view_circle = None
        self.scope_explicit = False
        self.view_kind = self.view_lang = self.view_domain = None
        self.view_stype = self.view_system = self.view_htype = None

    def on_rail(self, _event):
        sel = self.rail.selection()
        if not sel:
            return
        self.commit_if_dirty()
        iid = sel[0]
        key = iid[2:]
        if iid.startswith("s:"):
            self.clear_filters()
            self.scope = None if self.scope == key else key
            self.scope_explicit = self.scope is not None
        elif iid.startswith("v:"):
            was = self.viewmode
            self.clear_filters()
            self.viewmode = None if was == key else key
            self.scope = "people"
        elif iid.startswith("o:"):
            was = self.view_circle
            self.clear_filters()
            self.view_circle = None if was == key else key
            self.scope = "people"
        elif iid.startswith("t:"):
            was = self.tag
            self.clear_filters()
            self.tag = None if was == key else key
            self.scope = "people"
        elif iid.startswith("d:"):
            was = self.date
            self.clear_filters()
            self.date = None if was == key else key
            self.scope = "people"
        elif iid.startswith("k:"):
            was = self.view_kind
            self.clear_filters()
            self.view_kind = None if was == key else key
            self.scope = "entries"
        elif iid.startswith("l:"):
            was = self.view_lang
            self.clear_filters()
            self.view_lang = None if was == key else key
            self.scope = "entries"
        elif iid.startswith("m:"):
            was = self.view_domain
            self.clear_filters()
            self.view_domain = None if was == key else key
            self.scope = "entries"
        elif iid.startswith("y:"):
            was = self.view_stype
            self.clear_filters()
            self.view_stype = None if was == key else key
            self.scope = "sources"
        elif iid.startswith("u:"):
            was = self.view_htype
            self.clear_filters()
            self.view_htype = None if was == key else key
            self.scope = "corpus"
        elif iid.startswith("z:"):
            was = self.view_system
            self.clear_filters()
            self.view_system = None if was == key else key
            self.scope = "corpus"
        else:
            return
        self.rail.selection_remove(*self.rail.selection())
        self.refresh_rail()
        self.refresh_list()
        if self.scope == "corpus" and (self.sel is None
                                       or self.rec_kind(self.current()) != "metric"):
            self.show_corpus_blank()
        elif self.scope == "corpus":
            self.mc.map.set_current(self.view_system or (self.current() or {}).get("system"))

    def focus_list(self):
        self.list.focus_set()
        kids = self.list.get_children()
        if kids and not self.list.selection():
            self.list.selection_set(kids[0])

    def on_pick(self, _event):
        if self.busy:
            return
        sel = self.list.selection()
        if not sel or sel[0] == self.sel:
            return
        rid = sel[0]
        self.busy = True
        try:
            self.commit_if_dirty()
            if rid.startswith("x:"):
                self.show_cancelled(int(rid[2:]))
            elif self.list.exists(rid):
                self.open_record(rid)
            else:
                self.blank_card()
        finally:
            self.busy = False

    def blank_card(self):
        self.loading = True
        for c in self.cards.values():
            c.clear()
            c.enable(False)
        self.loading = False
        self.dirty = False
        self.sel = None
        self.set_locus(None)
        if getattr(self, "reader", None):
            self.reader.close(keep=False)

    def show_cancelled(self, n):
        """A cancelled number: the card stays empty and the header says what
        used to hold the number."""
        d = next((d for d in self.data.get("deleted", []) if d.get("reg_n") == n), None)
        self.blank_card()
        if d:
            self.locus.configure(
                text=tr("REGISTER Nº {n}    CANCELLED ON {at}  ·  {name}  ({id})", n=n,
                        at=(d.get("at") or "").replace("T", " "), name=d.get("name", ""),
                        id=d.get("id", "")))
            self.say(tr("Cancelled record: its history is in the log (Base › History)."))

    def open_record(self, rid):
        rec = by_id(self.data).get(rid)
        if not rec:
            return
        if self.reader.is_open and rid != self.reader.rid:
            self.reader.close()
        self.sel = rid
        self.loading = True
        kind = self.rec_kind(rec)
        self.show_card(kind)
        self.card.open(rec)
        self.set_locus(rec)
        for reset in self.undo_resets:
            try:
                reset()
            except Exception:
                pass
        self.show_in_list(rid)
        if self.list.exists(rid):
            self.list.selection_set(rid)
            self.list.see(rid)
        self.loading = False
        self.dirty = False
        self.refit_card()

    def goto(self, rid):
        if rid not in by_id(self.data):
            self.say(tr("{id} does not exist.", id=rid))
            return
        self.commit_if_dirty()
        self.busy = True
        try:
            self.open_record(rid)
        finally:
            self.busy = False

    def mark_dirty(self, _event=None):
        if not self.loading:
            self.dirty = True
            self.flash("")

    # ------------------------------------------------------------ writing
    def new_person(self):
        self.commit_if_dirty()
        self.draft = blank_person(self.q.get().strip())
        self.draft["id"] = "__draft_p__"
        self.draft["_h"] = ""
        self.data["people"].append(self.draft)
        self.refresh_list()
        self.open_record("__draft_p__")
        self.pc.e_name.focus_set()
        self.say(tr("New person. It only reaches the disk when saved."))

    def new_entry(self, kind):
        self.commit_if_dirty()
        self.draft = {"id": "__draft_e__", "kind": kind, "name": "", "gloss": "",
                      "tags": [], "notes": "", "source": "", "links": [],
                      "domains": [], "updated": None, "_h": ""}
        if kind == "form":
            self.draft.update({"lang": "", "roman": "", "attested": "",
                               "status": "attested"})
        self.data["entries"].append(self.draft)
        self.refresh_list()
        self.open_record("__draft_e__")
        self.vc.e_name.focus_set()
        self.say(tr("New entry. The id is generated when saved with a name."))

    def new_source(self):
        self.commit_if_dirty()
        raw = self.q.get().strip()
        self.draft = source_from_raw(raw) if raw else fix_source({"type": "livro"})
        self.draft["id"] = "__draft_s__"
        self.draft["_h"] = ""
        self.data["sources"].append(self.draft)
        self.refresh_list()
        self.open_record("__draft_s__")
        self.sc.e_name.focus_set()
        self.say(tr("New source. The id is generated when saved with a title."))

    def new_metric(self):
        self.commit_if_dirty()
        self.draft = fix_metric({"id": "__draft_h__", "name": self.q.get().strip(),
                                 "system": self.view_system or "",
                                 "ctype": self.view_htype or "measure"})
        self.draft["_h"] = ""
        self.data["corpus"].append(self.draft)
        self.refresh_list()
        self.open_record("__draft_h__")
        self.mc.e_name.focus_set()
        self.say(tr("New health record. The id is generated when saved with a name."))

    def _save_linked(self, coll, card, rec, auto, make_id_fn, needs_name):
        """Sources and measurements: the record plus the links going out of it,
        as with verba."""
        out = card.gather(rec)
        if not out["name"]:
            if not auto:
                self.flash(needs_name)
            return None
        if out["id"].startswith("__"):
            out["id"] = make_id_fn(out, set(by_id(load_json())))
        links = parse_edges(card.edges_text(), out["id"])
        unparsed = [a["to"] for a in links if a.get("_bad")]
        links = [a for a in links if not a.get("_bad")]
        if unparsed:
            out["edge_drafts"] = unparsed
        else:
            out.pop("edge_drafts", None)
        touch(out)
        self.data = save_record(coll, out, edges=links)
        self.safe_mirror(self.data)
        if unparsed:
            self.say(tr("{n} link line(s) not understood were kept as drafts.", n=len(unparsed)))
        elif auto:
            self.say(tr('Saved "{name}" automatically.', name=one_liner(out["name"], 40)))
        return out["id"]

    def save(self, reopen=True, auto=False):
        self.reader.sync()
        if not self.sel:
            return None
        rec = self.current()
        if not rec:
            return None
        kind = self.rec_kind(rec)
        old_id = rec["id"]
        self._reshaped = False          # set when saving changes what the card shows
        try:
            if kind == "person":
                new_id = self._save_person(rec, auto)
            elif kind == "entry":
                new_id = self._save_entry(rec, auto)
            elif kind == "source":
                new_id = self._save_linked("sources", self.sc, rec, auto, new_source_id,
                                           tr("A source needs a name."))
            else:
                new_id = self._save_linked("corpus", self.mc, rec, auto, new_metric_id,
                                           tr("A measurement needs a name."))
        except SystemExit as exc:
            self.notify(tr("Not saved"), str(exc))
            return None
        if new_id is None:
            return None
        self.draft = None
        self.dirty = False
        self.sel = new_id
        self.reload()
        if reopen and (new_id != old_id or self._reshaped):
            self.open_record(new_id)
        elif reopen:
            # the card already shows what was saved: refresh only what the save
            # itself changes (number, stamp, resolved links) instead of
            # rebuilding every field
            saved = self.current()
            self.set_locus(saved)
            card = self.card
            if hasattr(card, "refresh_neighbours"):
                card.refresh_neighbours(new_id)
            elif hasattr(card, "refresh_citing"):
                card.refresh_citing(saved)
            if self.list.exists(new_id):
                self.list.selection_set(new_id)
        if reopen:
            self.flash(tr("Saved {date}", date=TODAY()))
        return new_id

    def _save_person(self, p, auto):
        rec = self.pc.gather(p)
        if not rec["name"]:
            if not auto:
                self.flash(tr("A person needs a name."))
            return None
        filed = fold_finished_tasks(rec)
        self._reshaped = self._reshaped or bool(filed)     # finished tasks moved to the log
        if rec["id"].startswith("__"):
            rec["met"] = rec.get("met") or TODAY()
            rec["id"] = make_id(rec["name"], set(by_id(load_json())))
        touch(rec)
        self.data = save_record("people", rec)
        self.safe_mirror(self.data)
        if filed:
            self.say(tr("{n} finished task(s) went to the log.", n=filed))
        elif auto:
            self.say(tr('Saved "{name}" automatically.', name=one_liner(rec["name"], 40)))
        return rec["id"]

    def _save_entry(self, e, auto):
        rec = self.vc.gather(e)
        if not rec["name"]:
            if not auto:
                self.flash(tr("An entry needs a name."))
            return None
        old = rec["id"]
        if old.startswith("__"):
            rec["id"] = new_id(rec["kind"], rec["name"], set(by_id(load_json())))
        links = parse_edges(self.vc.edges_text(), rec["id"])
        unparsed = [a["to"] for a in links if a.get("_bad")]
        links = [a for a in links if not a.get("_bad")]
        if unparsed:
            rec["edge_drafts"] = unparsed
        else:
            rec.pop("edge_drafts", None)
        touch(rec)
        self.data = save_record("entries", rec, edges=links)
        self.safe_mirror(self.data)
        if unparsed:
            self.say(tr("{n} link line(s) not understood were kept as drafts.", n=len(unparsed)))
        elif auto:
            self.say(tr('Saved "{name}" automatically.', name=one_liner(rec["name"], 40)))
        return rec["id"]

    def commit_if_dirty(self):
        self.reader.sync()
        if not self.dirty or not self.sel:
            return
        if not self.card.e_name.get().strip():
            self.dirty = False
            if self.sel.startswith("__"):
                self.draft = None
            return
        self.save(reopen=False, auto=True)

    def save_and_new(self):
        rec = self.current()
        kind = self.rec_kind(rec)
        ekind = (rec or {}).get("kind", "concept")
        if self.save() is not None:
            {"person": self.new_person, "source": self.new_source,
             "metric": self.new_metric,
             "entry": lambda: self.new_entry(ekind)}[kind]()

    def delete(self):
        rec = self.current()
        if not rec:
            return
        if rec["id"].startswith("__"):
            self.draft = None
            self.sel = None
            self.reload()
            self.blank_card()
            return
        n = len(edges_from(self.data, rec["id"])) + len(edges_to(self.data, rec["id"]))
        msg = tr('Delete "{label}"?', label=label_any(rec, self.data))
        if n:
            msg += "\n\n" + tr("{n} link(s) involving this record go too.", n=n)
        msg += "\n\n" + tr("The log keeps the previous version (Base › History).")
        if not self.confirm(tr("Delete"), msg, yes=tr("Delete")):
            return
        coll = coll_of(rec["id"])
        self.data, _ = delete_record(coll, rec["id"], rec.get("name", ""))
        self.safe_mirror(self.data)
        self.sel = None
        self.reload()
        self.blank_card()
        self.say(tr("Deleted. The previous version is in the log."))

    def known_langs(self):
        langs = {e.get("lang") for e in self.data["entries"]
                 if e.get("kind") == "form" and e.get("lang")}
        return sorted(langs, key=sort_key)

    def quick_add(self):
        """Several entries at once, one per line."""
        self.commit_if_dirty()
        win = self.dialog(tr("Quick entry"), 640, 520)
        tk.Label(win, text=tr("QUICK ENTRY"), bg=PAPER, fg=FAINT,
                 font=self.f_label).pack(anchor="w", padx=20, pady=(16, 2))
        hint = tk.Label(win, text="", bg=PAPER, fg=SOFT, font=self.f_meta,
                        justify="left")
        hint.pack(anchor="w", padx=20, pady=(0, 10))
        row = tk.Frame(win, bg=PAPER)
        row.pack(fill="x", padx=20)

        def col(title, width, pad):
            c = tk.Frame(row, bg=PAPER)
            c.pack(side="left", padx=pad, fill="x" if width is None else None,
                   expand=width is None)
            tk.Label(c, text=title, bg=PAPER, fg=FAINT, font=self.f_label,
                     anchor="w").pack(fill="x", pady=(0, 2))
            return c

        kinds = {tr(k): k for k in ("person", "form", "concept", "source")}
        v_kind = tk.StringVar(value=tr("person"))
        kb = ttk.Combobox(col(tr("KIND"), 10, 0), textvariable=v_kind, state="readonly",
                          values=list(kinds), width=10, font=self.f_meta)
        kb.pack()
        v_lang = tk.StringVar(value="")
        lang_box = ttk.Combobox(col(tr("LANGUAGE"), 12, (14, 0)), textvariable=v_lang,
                                values=self.known_langs(), width=12, font=self.f_meta)
        lang_box.pack()
        e_source = tk.Entry(col(tr("SOURCE"), None, (14, 0)), font=self.f_meta, bg=PAPER,
                            fg=INK, insertbackground=INK, relief="flat",
                            highlightthickness=1, highlightbackground=RULE,
                            highlightcolor=STAMP)
        e_source.pack(fill="x", ipady=2)

        def toggle(*_a):
            k = kinds.get(v_kind.get(), "person")
            lang_box.configure(state="normal" if k == "form" else "disabled")
            e_source.configure(state="normal" if k != "person" else "disabled")
            hint.configure(text={"person": tr("One per line:  - Name. Notes about the person."),
                                 "source": tr("One reference per line, as you would write it "
                                              "(SURNAME, Name. Title. Place: Publisher, year)."),
                                 }.get(k, tr("One per line:  name. gloss")))

        v_kind.trace_add("write", toggle)
        toggle()
        tk.Label(win, text="", bg=PAPER).pack(pady=2)
        box = tk.Text(win, height=10, font=self.f_meta, bg=SHELL, fg=INK,
                      insertbackground=INK, relief="flat", wrap="word",
                      highlightthickness=1, highlightbackground=RULE,
                      highlightcolor=STAMP, padx=8, pady=6, undo=True)
        self.bind_undo(box, text=True)
        box.pack(fill="both", expand=True, padx=20)

        def add():
            kind = kinds.get(v_kind.get(), "person")
            text = box.get("1.0", "end-1c")
            if not text.strip():
                win.destroy()
                return
            if kind == "person":
                if not text.lstrip().startswith(("- ", "* ", "## ")):
                    text = "\n".join("- " + l.strip() for l in text.splitlines()
                                     if l.strip())
                data = load_json()
                added, merged, identical, names = ingest(text, data)
                write_json(data)
                self.safe_mirror(data)
                win.destroy()
                self.reload()
                bits = []
                if added:
                    bits.append(tr("{n} added", n=added))
                if merged:
                    bits.append(tr("{n} got an addendum: ", n=merged)
                                + ", ".join(one_liner(n, 28) for n in names[:3]))
                if identical:
                    bits.append(tr("{n} were already there", n=identical))
                self.say(" · ".join(bits) or tr("Nothing to add."))
                return
            if kind == "source":
                items = [source_from_raw(l) for l in text.splitlines() if l.strip()]
                data = load_json()
                added, skipped = import_sources(items, data)
                write_json(data)
                self.safe_mirror(data)
                win.destroy()
                self.reload()
                self.say(tr("{added} source(s) added, {skipped} already existed.",
                            added=added, skipped=skipped))
                return
            lang = v_lang.get().strip()
            src = e_source.get().strip()
            if kind == "form" and not lang:
                hint.configure(text=tr("A form needs a language."))
                return
            data = load_json()
            taken = set(by_id(data))
            made = 0
            for line in text.splitlines():
                line = line.strip()
                if line[:2] in ("- ", "* "):
                    line = line[2:].strip()
                if not line:
                    continue
                name, gloss = (line.split(". ", 1) if ". " in line else (line, ""))
                name, gloss = name.strip(), gloss.strip()
                if not name:
                    continue
                eid = new_id(kind, name, taken)
                taken.add(eid)
                rec = fix_entry({"id": eid, "kind": kind, "name": name, "gloss": gloss,
                                 "source": src})
                if kind == "form":
                    rec.update({"lang": lang,
                                "status": "reconstructed" if name.startswith("*")
                                else "attested"})
                touch(rec)
                data["entries"].append(rec)
                log_put("entries", rec)
                made += 1
            if made:
                write_json(data)
                self.safe_mirror(data)
            win.destroy()
            self.reload()
            self.say(tr("{n} entry(ies) added.", n=made)
                     + (tr(" Concepts without a gloss show up in Check structure.")
                        if kind == "concept" and made else ""))

        foot = tk.Frame(win, bg=PAPER)
        foot.pack(fill="x", padx=20, pady=14)
        ttk.Button(foot, text=tr("Add"), command=add).pack(side="left")
        ttk.Button(foot, text=tr("Cancel"), style="Quiet.TButton",
                   command=win.destroy).pack(side="left", padx=(8, 0))
        win.bind("<Escape>", lambda e: win.destroy())
        box.focus_set()

    # ------------------------------------------------------------ base
    MIRROR_DELAY = 1500       # ms after the last save before the mirror is rebuilt

    def safe_mirror(self, data, now=False):
        """Rebuilds the markdown mirror and the body-map page. They are only
        readable copies, so this happens off the save: 1.5 s after the last
        save, in a thread, on a snapshot of the data -- typing and saving never
        wait for it. `now` (and closing the window) does it immediately."""
        try:
            self._mirror_blob = marshal.dumps(data)
        except ValueError:
            self._mirror_blob = None
            now = True
        if getattr(self, "_mirror_job", None):
            try:
                self.root.after_cancel(self._mirror_job)
            except tk.TclError:
                pass
            self._mirror_job = None
        if now:
            self.flush_mirror(data)
        else:
            self._mirror_job = self.root.after(self.MIRROR_DELAY, self.start_mirror)

    def start_mirror(self):
        import threading
        self._mirror_job = None
        busy = getattr(self, "_mirror_thread", None)
        if busy is not None and busy.is_alive():          # one at a time
            self._mirror_job = self.root.after(300, self.start_mirror)
            return
        blob, self._mirror_blob = getattr(self, "_mirror_blob", None), None
        if blob is None:
            return
        self._mirror_error = None

        def work():
            try:
                snapshot = marshal.loads(blob)
                write_mirror(snapshot)
                write_corpus_html(snapshot)
            except SystemExit as exc:
                self._mirror_error = str(exc)
            except OSError as exc:
                self._mirror_error = str(exc)

        self._mirror_thread = threading.Thread(target=work, daemon=True)
        self._mirror_thread.start()
        self.root.after(200, self.check_mirror)

    def check_mirror(self):
        t = getattr(self, "_mirror_thread", None)
        if t is not None and t.is_alive():
            self.root.after(200, self.check_mirror)
        elif getattr(self, "_mirror_error", None):
            err, self._mirror_error = self._mirror_error, None
            self.notify(tr("Mirror not rebuilt"), err)

    def flush_mirror(self, data=None):
        """Finishes the mirror now: waits for a running rebuild, then writes
        whatever is still pending (used on close)."""
        if getattr(self, "_mirror_job", None):
            try:
                self.root.after_cancel(self._mirror_job)
            except tk.TclError:
                pass
            self._mirror_job = None
        t = getattr(self, "_mirror_thread", None)
        if t is not None and t.is_alive():
            t.join(10)
        blob, self._mirror_blob = getattr(self, "_mirror_blob", None), None
        if data is None and blob is not None:
            data = marshal.loads(blob)
        if data is None:
            return
        try:
            write_mirror(data)
        except SystemExit as exc:
            self.notify(tr("Mirror not rebuilt"), str(exc))
        try:
            write_corpus_html(data)
        except OSError:
            pass

    def do_corpus(self):
        self.commit_if_dirty()
        import io
        import contextlib
        with contextlib.redirect_stdout(io.StringIO()):
            cmd_corpus(open_it=True)
        self.say(tr("Body map rebuilt and opened: {name}", name=CORPUS_HTML_FILE.name))

    def do_health(self):
        self.commit_if_dirty()
        import io
        import contextlib
        with contextlib.redirect_stdout(io.StringIO()):
            cmd_health(open_it=True)
        self.say(tr("Health report made and opened: {name}", name=HEALTH_HTML_FILE.name))

    def do_mirror(self):
        self.commit_if_dirty()
        self.safe_mirror(load_json(), now=True)
        self.say(tr("Mirror rebuilt: {name}", name=MIRROR_FILE.name))

    def do_doctor(self):
        self.commit_if_dirty()
        errors, warnings = check(self.data)
        body = summary(self.data) + "\n" + tr("{e} errors, {w} warnings", e=len(errors),
                                              w=len(warnings)) + ".\n\n"
        body += "\n".join(errors[:20]) if errors else tr("No structural errors.")
        if warnings:
            body += "\n\n" + "\n".join(warnings[:20])
        others = other_locks()
        if others:
            body += "\n\n" + tr("Also open on: ") + ", ".join(
                tr("{host} since {since}", host=o.get("host"), since=o.get("since"))
                for o in others)
        self.show_text(tr("Structure"), body)

    def do_normalize(self):
        self.commit_if_dirty()
        if not self.confirm(tr("Normalize inline tags"),
                            tr("Move #hashtags and dates written in people's names and "
                               "notes into the tags field?"), yes=tr("Normalize")):
            return
        import io
        import contextlib
        with contextlib.redirect_stdout(io.StringIO()):
            cmd_normalize()
        self.reload()
        self.say(tr("Normalized."))

    def do_merge(self):
        self.commit_if_dirty()
        reports = absorb_conflicts()
        if not reports:
            self.say(tr("No conflict files in the folder."))
            return
        self.safe_mirror(load_json())
        self.reload()
        body = []
        for name, r in reports:
            body.append(name)
            for coll, rid, nm in r["added"]:
                body.append(f"  + {nm}  ({rid})")
            for coll, rid, nm in r["replaced"]:
                body.append(f"  ~ {nm}  ({rid})")
            for coll, rid, nm in r["skipped_deleted"]:
                body.append(f"  - {nm}  ({rid}, " + tr("deleted") + ")")
            body.append("  " + tr("{n} kept", n=r["kept"]) + "\n")
        self.show_text(tr("Conflicts merged"), "\n".join(body))

    def do_history(self):
        rec = self.current()
        if not rec or rec["id"].startswith("__"):
            self.say(tr("Open a saved record first."))
            return
        import io
        import contextlib
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            cmd_history(rec["id"])
        self.show_text(tr("History · {label}", label=label_any(rec)), buf.getvalue())

    def do_import_zotero(self):
        from tkinter import filedialog
        path = filedialog.askopenfilename(
            title=tr("Zotero export (CSL-JSON or BibTeX)"),
            filetypes=[("CSL-JSON / BibTeX", "*.json *.bib"), (tr("All files"), "*.*")])
        if not path:
            return
        import io
        import contextlib
        buf = io.StringIO()
        try:
            with contextlib.redirect_stdout(buf):
                cmd_import_zotero(path)
        except (SystemExit, ValueError, json.JSONDecodeError) as exc:
            self.notify(tr("Import"), str(exc))
            return
        self.reload()
        self.say(buf.getvalue().strip())

    def do_export(self, fmt):
        import io
        import contextlib
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            cmd_export(fmt)
        self.say(buf.getvalue().strip() + "  " + tr("(in {dir})", dir=BASE))

    def card_layout_dialog(self):
        win = self.dialog(tr("Entry card fields"), 460, 480)
        tk.Label(win, text=tr("ENTRY CARD FIELDS"), bg=PAPER, fg=FAINT,
                 font=self.f_label).pack(anchor="w", padx=18, pady=(16, 2))
        tk.Label(win, text=tr("Space shows or hides. The arrows move."),
                 bg=PAPER, fg=SOFT, font=self.f_meta).pack(anchor="w", padx=18,
                                                          pady=(0, 8))
        box = tk.Listbox(win, height=11, font=self.f_meta, bg=PAPER, fg=INK,
                         relief="flat", highlightthickness=0, selectbackground=SELBG,
                         selectforeground=SELFG, activestyle="none")
        box.pack(fill="both", expand=True, padx=18)
        work = list(self.vc.layout)

        def redraw(keep=0):
            box.delete(0, "end")
            for fid, on in work:
                box.insert("end", f"[{'x' if on else ' '}]  {tr(FIELD_TITLE[fid])}")
            if work:
                box.selection_clear(0, "end")
                box.selection_set(min(keep, len(work) - 1))
                box.activate(min(keep, len(work) - 1))

        def move(step):
            sel = box.curselection()
            if not sel:
                return "break"
            i = sel[0]
            j = i + step
            if 0 <= j < len(work):
                work[i], work[j] = work[j], work[i]
                redraw(j)
            return "break"

        def toggle(_e=None):
            sel = box.curselection()
            if not sel:
                return "break"
            i = sel[0]
            work[i] = (work[i][0], not work[i][1])
            redraw(i)
            return "break"

        box.bind("<space>", toggle)
        box.bind("<Double-Button-1>", toggle)
        row = tk.Frame(win, bg=PAPER)
        row.pack(fill="x", padx=18, pady=12)
        ttk.Button(row, text="↑", width=3, command=lambda: move(-1)).pack(side="left")
        ttk.Button(row, text="↓", width=3, command=lambda: move(1)).pack(side="left",
                                                                        padx=(4, 0))
        ttk.Button(row, text=tr("show / hide"), style="Quiet.TButton",
                   command=toggle).pack(side="left", padx=(10, 0))

        def restore():
            work[:] = [(f, True) for f in FIELD_IDS]
            redraw(0)

        def apply_now():
            self.vc.layout = list(work)
            self.save_prefs({"card_fields": [{"id": f, "on": on} for f, on in work]})
            self.vc.apply_layout()
            win.destroy()
            self.say(tr("Fields rearranged."))

        row2 = tk.Frame(win, bg=PAPER)
        row2.pack(fill="x", padx=18, pady=(0, 14))
        ttk.Button(row2, text=tr("Use"), command=apply_now).pack(side="left")
        ttk.Button(row2, text=tr("Default"), style="Quiet.TButton",
                   command=restore).pack(side="left", padx=(8, 0))
        ttk.Button(row2, text=tr("Cancel"), style="Quiet.TButton",
                   command=win.destroy).pack(side="left", padx=(8, 0))
        win.bind("<Escape>", lambda e: win.destroy())
        redraw(0)
        box.focus_set()

    def choose_typeface(self):
        fams = self.mono_families()
        win = self.dialog(tr("Terminal typeface"), 420, 460)
        tk.Label(win, text=tr("TERMINAL TYPEFACE"), bg=PAPER, fg=FAINT,
                 font=self.f_label).pack(anchor="w", padx=18, pady=(14, 2))
        tk.Label(win, text=tr("Monospaced faces only: any other misaligns\n"
                              "the columns and the block cursor."),
                 bg=PAPER, fg=SOFT, font=self.f_meta, justify="left"
                 ).pack(anchor="w", padx=18, pady=(0, 8))
        box = tk.Listbox(win, height=12, width=34, font=self.f_meta, bg=PAPER, fg=INK,
                         relief="flat", highlightthickness=0, selectbackground=SELBG,
                         selectforeground=SELFG, activestyle="none")
        box.pack(fill="both", expand=True, padx=18)
        box.insert("end", tr("(default)"))
        for fam in fams:
            box.insert("end", fam)
        current = (self.data.get("ui") or {}).get("font_mono")
        if current in fams:
            idx = fams.index(current) + 1
            box.selection_set(idx)
            box.see(idx)
        else:
            box.selection_set(0)
        row = tk.Frame(win, bg=PAPER)
        row.pack(fill="x", padx=18, pady=12)

        def apply():
            sel = box.curselection()
            pick = None if not sel or sel[0] == 0 else fams[sel[0] - 1]
            save_ui({"font_mono": pick})
            win.destroy()
            self.commit_if_dirty()
            self.restart_theme = self.theme
            self.flush_mirror()
            self.stop_carets()
            self.root.destroy()

        ttk.Button(row, text=tr("Use"), command=apply).pack(side="left")
        ttk.Button(row, text=tr("Cancel"), style="Quiet.TButton",
                   command=win.destroy).pack(side="left", padx=(8, 0))
        win.bind("<Escape>", lambda e: win.destroy())

    def switch_theme(self, key):
        if key == self.theme:
            return
        self.commit_if_dirty()
        save_ui({"theme": key})
        self.restart_theme = key
        self.flush_mirror()
        self.stop_carets()
        self.root.destroy()

    def switch_language(self, code):
        """View › Language: stored in ui.lang; the window is rebuilt in it."""
        if code == LANG:
            return
        self.commit_if_dirty()
        save_ui({"lang": code})
        set_lang(code)
        self.restart_theme = self.theme
        self.flush_mirror()
        self.stop_carets()
        self.root.destroy()

    def do_help(self):
        self.show_text(tr("Shortcuts"), tr(HELP_TEXT, conflicts=CONFLICT_DIR.name, stem=STEM)
                       + tr(HELP_READING) + tr(HELP_COPY))

    # ------------------------------------------------------------ dialogs
    def dialog(self, title, width=520, height=None):
        win = tk.Toplevel(self.root)
        win.title(title)
        win.configure(bg=PAPER)
        win.transient(self.root)
        self.root.update_idletasks()
        x = self.root.winfo_rootx() + (self.root.winfo_width() - width) // 2
        y = self.root.winfo_rooty() + 120
        win.geometry(f"{width}x{height or 200}+{max(0, x)}+{max(0, y)}")
        paint_frame(win)
        return win

    def confirm(self, title, message, yes=None, no=None):
        yes, no = yes or tr("Yes"), no or tr("Cancel")
        win = self.dialog(title, 560, 230)
        answer = {"v": False}
        tk.Label(win, text=title, bg=PAPER, fg=INK,
                 font=(self.f_body[0], 14)).pack(anchor="w", padx=20, pady=(18, 6))
        tk.Label(win, text=message, bg=PAPER, fg=SOFT, font=self.f_meta,
                 justify="left", wraplength=510).pack(anchor="w", padx=20)
        row = tk.Frame(win, bg=PAPER)
        row.pack(fill="x", side="bottom", padx=20, pady=16)

        def close(value):
            answer["v"] = value
            win.destroy()

        ttk.Button(row, text=yes, command=lambda: close(True)).pack(side="left")
        ttk.Button(row, text=no, style="Quiet.TButton",
                   command=lambda: close(False)).pack(side="left", padx=10)
        win.bind("<Escape>", lambda e: close(False))
        win.bind("<Return>", lambda e: close(True))
        win.grab_set()
        win.focus_set()
        self.root.wait_window(win)
        return answer["v"]

    def notify(self, title, message):
        win = self.dialog(title, 560, 220)
        tk.Label(win, text=title, bg=PAPER, fg=OXIDE,
                 font=(self.f_body[0], 14)).pack(anchor="w", padx=20, pady=(18, 6))
        tk.Label(win, text=message, bg=PAPER, fg=INK, font=self.f_meta,
                 justify="left", wraplength=510).pack(anchor="w", padx=20)
        ttk.Button(win, text=tr("OK"), command=win.destroy).pack(side="bottom", anchor="w",
                                                             padx=20, pady=16)
        win.bind("<Escape>", lambda e: win.destroy())
        win.bind("<Return>", lambda e: win.destroy())
        win.grab_set()
        win.focus_set()
        self.root.wait_window(win)

    def show_text(self, title, body):
        win = tk.Toplevel(self.root)
        win.title(title)
        win.configure(bg=PAPER)
        win.geometry("700x480")
        win.transient(self.root)
        paint_frame(win)
        t = tk.Text(win, font=self.f_meta, bg=PAPER, fg=INK, relief="flat",
                    wrap="word", padx=16, pady=14)
        t.pack(fill="both", expand=True)
        t.insert("1.0", body)
        t.configure(state="disabled")
        win.bind("<Escape>", lambda e: win.destroy())

    def on_close(self):
        self.commit_if_dirty()
        self.flush_mirror()
        self.stop_carets()
        self.root.destroy()


# ================================================================ livro
#
# READ-ONLY: the base seen as a logbook, in two-page spreads that turn. The
# left page is the roll (numbered records); the right page is the folio of the
# chosen record. Everything is drawn on a Canvas, in two inks, with Tk's own
# stipple standing in for halftone. It reads the JSON once and writes nothing:
# no base, no log, no lock.

BOOK_PALETTES = {
    "paper": {"desk": "#2e2b25", "paper": "#e9e3d1", "ink": "#26241f", "hint": "#a59f8d"},
    "night": {"desk": "#0b0a08", "paper": "#18160f", "ink": "#e3b45f", "hint": "#8a6d3a"},
    "sea":   {"desk": "#1b2422", "paper": "#d9e0d6", "ink": "#1f3a35", "hint": "#8fa39c"},
}
BOOK_CHAPTERS = [("register", "Register"), ("people", "People"),
                 ("entries", "Verba"), ("sources", "Sources"), ("corpus", "Corpus")]
KIND_TAG = {"person": "person", "concept": "concept", "form": "form",
            "source": "source", "metric": "measurement"}
KIND_SHORT = {"person": "per", "concept": "con", "form": "frm",
              "source": "src", "metric": "msr"}


class BookView:
    TURN_FRAMES = 14
    TURN_MS = 15

    def __init__(self, root, data, start_id=None, on_open=None):
        self.root, self.data = root, data
        self.on_open = on_open     # from the main window: open the record on the card
        self.idx = by_id(data)
        self.pal_name = "paper"
        self.animate = True
        self.spreads = []          # [("front",)] + [("list", chapter, page)]
        self.cur = 0               # open spread
        self.sel = 0               # chosen line in the roll
        self.busy = False
        self._job = None
        fams = set(tkfont.families(root))
        mono = next((f for f in ("Cascadia Mono", "Consolas", "Lucida Console",
                                 "DejaVu Sans Mono", "Courier New") if f in fams), "Courier")
        serif = next((f for f in ("Georgia", "Times New Roman", "Liberation Serif",
                                  "DejaVu Serif") if f in fams), "Times")
        self.f_body = tkfont.Font(root, family=mono, size=10)
        self.f_small = tkfont.Font(root, family=mono, size=8)
        self.f_title = tkfont.Font(root, family=serif, size=22)
        self.f_big = tkfont.Font(root, family=serif, size=40)
        self.f_head = tkfont.Font(root, family=serif, size=13, slant="italic")
        self.cw = self.f_body.measure("0")
        self.lh = self.f_body.metrics("linespace") + 7

        root.title(tr("Kustos · logbook (read-only)"))
        sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
        w, h = min(1240, sw - 80), min(780, sh - 120)
        root.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+{max(0, (sh - h) // 3)}")
        root.minsize(820, 520)
        self.cv = tk.Canvas(root, highlightthickness=0, bd=0)
        self.cv.pack(fill="both", expand=True)
        self.chapters = self.build_chapters()
        self.pending = None        # record the logbook opens on
        for i, (_, o) in enumerate(self.chapters["register"]):
            if start_id and o.get("id") == start_id:
                self.pending = ("register", i)

        b = root.bind
        for k in ("<Next>", "<Right>", "<space>"):
            b(k, lambda e: self.turn(1))
        for k in ("<Prior>", "<Left>", "<BackSpace>"):
            b(k, lambda e: self.turn(-1))
        b("<Down>", lambda e: self.step(1))
        b("<Up>", lambda e: self.step(-1))
        b("<Home>", lambda e: self.open_spread(0, -1))
        b("<End>", lambda e: self.open_spread(len(self.spreads) - 1, 1))
        b("<MouseWheel>", lambda e: self.turn(-1 if e.delta > 0 else 1))
        b("<Button-4>", lambda e: self.turn(-1))
        b("<Button-5>", lambda e: self.turn(1))
        for n, (key, _) in enumerate(BOOK_CHAPTERS, 1):
            b(str(n), lambda e, k=key: self.open_chapter(k))
        b("<t>", lambda e: self.cycle_palette())
        b("<c>", lambda e: self.copy_id())
        b("<a>", lambda e: self.toggle_animation())
        b("<Return>", lambda e: self.open_in_card())
        self.cv.bind("<Double-Button-1>", lambda e: self.open_in_card())
        b("<Escape>", lambda e: root.destroy())
        b("<q>", lambda e: root.destroy())
        self.cv.bind("<Button-1>", self.click)
        self.cv.bind("<Configure>", self.resized)

    # ---------------------------------------------------------- content
    def build_chapters(self):
        """Each chapter is an ordered list of (kind, object): "r" a live record,
        "x" a cancelled number."""
        data = self.data
        live = {r["reg_n"]: r for c in COLLS for r in data[c] if r.get("reg_n")}
        gone = {d["reg_n"]: d for d in data.get("deleted", [])
                if d.get("reg_n") and d["reg_n"] not in live}
        out = {"register": [("r", live[n]) if n in live else ("x", gone[n])
                            for n in sorted(set(live) | set(gone))]}
        for coll in ("people", "entries", "sources", "corpus"):
            rows = sorted((r for r in data[coll] if not r["id"].startswith("__")),
                          key=lambda r: sort_key(label_any(r, data)))
            out[coll] = [("r", r) for r in rows]
        return out

    def paginate(self):
        """Rebuilds the pages for the current window size, keeping open the
        record that was open."""
        keep = self.current_rec() or self.pending
        self.pending = None
        self.spreads = [("front",)]
        per = max(4, self.list_rows())
        for key, _ in BOOK_CHAPTERS:
            items = self.chapters[key]
            for p in range(max(1, -(-len(items) // per))):
                self.spreads.append(("list", key, p))
        self.per = per
        self.cur = min(self.cur, len(self.spreads) - 1)
        if keep:
            self.reveal(keep)

    def reveal(self, target):
        """Opens the spread where `target` (key, index) is."""
        key, i = target
        for n, s in enumerate(self.spreads):
            if s[0] == "list" and s[1] == key and s[2] == i // self.per:
                self.cur, self.sel = n, i % self.per
                return

    def page_items(self, n=None):
        s = self.spreads[self.cur if n is None else n]
        if s[0] != "list":
            return []
        items = self.chapters[s[1]]
        return items[s[2] * self.per:(s[2] + 1) * self.per]

    def current_rec(self):
        s = self.spreads[self.cur] if self.spreads else ("front",)
        if s[0] != "list":
            return None
        return (s[1], s[2] * self.per + self.sel)

    # ---------------------------------------------------------- geometry
    def geometry(self):
        W, H = max(self.cv.winfo_width(), 200), max(self.cv.winfo_height(), 200)
        aw, ah = W - 56, H - 56 - 22
        ratio = 1.46
        if aw / ah > ratio:
            bh = ah
            bw = bh * ratio
        else:
            bw = aw
            bh = bw / ratio
        x0, y0 = (W - bw) / 2, (H - 22 - bh) / 2
        self.W, self.H = W, H
        self.book = (x0, y0, x0 + bw, y0 + bh)
        self.spine = x0 + bw / 2
        self.pad = max(22, bw * 0.04)

    def list_rows(self):
        self.geometry()
        x0, y0, x1, y1 = self.book
        usable = (y1 - y0) - 2 * self.pad - 70
        return int(usable // self.lh)

    # ---------------------------------------------------------- drawing
    def ink(self):
        return BOOK_PALETTES[self.pal_name]

    def draw(self):
        cv, P = self.cv, self.ink()
        cv.delete("all")
        cv.configure(bg=P["desk"])
        x0, y0, x1, y1 = self.book
        # the cover's shadow and the stacked leaves at the edge
        cv.create_rectangle(x0 + 6, y0 + 8, x1 + 6, y1 + 8, fill=P["ink"], outline="",
                            stipple="gray50")
        for k in (3, 2, 1):
            cv.create_rectangle(x0 - k * 2, y0 + k, x1 + k * 2, y1 + k,
                                fill=P["paper"], outline=P["ink"], width=1)
        cv.create_rectangle(x0, y0, x1, y1, fill=P["paper"], outline=P["ink"], width=1)
        # spine: a halftone that darkens toward the fold
        for w, st in ((26, "gray12"), (14, "gray25"), (5, "gray50")):
            cv.create_rectangle(self.spine - w, y0, self.spine + w, y1,
                                fill=P["ink"], outline="", stipple=st)
        cv.create_line(self.spine, y0, self.spine, y1, fill=P["ink"])
        s = self.spreads[self.cur]
        if s[0] == "front":
            self.draw_title_page()
            self.draw_contents_page()
        else:
            self.draw_list_page(s)
            self.draw_folio()
        self.draw_footer()

    def page_box(self, side):
        x0, y0, x1, y1 = self.book
        p = self.pad
        if side == "left":
            return x0 + p, y0 + p, self.spine - p, y1 - p
        return self.spine + p, y0 + p, x1 - p, y1 - p

    def rule(self, x0, x1, y, double=False):
        P = self.ink()
        self.cv.create_line(x0, y, x1, y, fill=P["ink"])
        if double:
            self.cv.create_line(x0, y + 3, x1, y + 3, fill=P["ink"])

    def text(self, x, y, s, font=None, anchor="nw", fill=None, width=None, tags=()):
        kw = {"width": width} if width else {}
        return self.cv.create_text(x, y, text=s, font=font or self.f_body, anchor=anchor,
                                   fill=fill or self.ink()["ink"], tags=tags, **kw)

    def draw_title_page(self):
        P = self.ink()
        bx0, by0, bx1, by1 = self.page_box("left")
        cx = (bx0 + bx1) / 2
        self.cv.create_rectangle(bx0, by0, bx1, by1, outline=P["ink"])
        self.cv.create_rectangle(bx0 + 5, by0 + 5, bx1 - 5, by1 - 5, outline=P["ink"])
        cy = by0 + (by1 - by0) * 0.28
        for r, st in ((62, "gray12"), (46, "gray25"), (30, "gray50")):
            pts = [c for xy in ellipse_points(cx, cy, r, r, n=48) for c in xy]
            self.cv.create_polygon(*pts, fill=P["ink"], outline=P["ink"], stipple=st)
        pts = [c for xy in ellipse_points(cx, cy, 14, 14, n=32) for c in xy]
        self.cv.create_polygon(*pts, fill=P["paper"], outline=P["ink"])
        t = self.text(cx, cy + 84, "KUSTOS", self.f_big, "n")
        y = self.cv.bbox(t)[3] + 6
        subject = (self.data.get("ui") or {}).get("corpus_subject") or ""
        t = self.text(cx, y, tr("register of {name}", name=subject) if subject else tr("register"),
                      self.f_head, "n", width=bx1 - bx0 - 40)
        self.cv.itemconfigure(t, justify="center")
        y = self.cv.bbox(t)[3] + 8
        opened = ((self.data.get("book") or {}).get("opened") or "")[:10]
        if opened:
            self.text(cx, y, tr("opened on {date}", date=opened), self.f_small, "n")
        self.text(cx, by1 - 28, summary(self.data), self.f_small, "s",
                  width=bx1 - bx0 - 40)

    def draw_contents_page(self):
        bx0, by0, bx1, by1 = self.page_box("right")
        self.text((bx0 + bx1) / 2, by0 + 6, tr("Contents"), self.f_title, "n")
        self.rule(bx0, bx1, by0 + 52, double=True)
        y = by0 + 78
        cols = int((bx1 - bx0) // self.cw)
        for n, (key, title) in enumerate(BOOK_CHAPTERS, 1):
            first = next(i for i, s in enumerate(self.spreads)
                         if s[0] == "list" and s[1] == key)
            label = f"{n}  {tr(title)}  ({len(self.chapters[key])})"
            page = str(first * 2 + 1)
            dots = "." * max(2, cols - len(label) - len(page) - 2)
            self.text(bx0, y, f"{label} {dots} {page}", tags=("toc", f"toc:{key}"))
            y += self.lh + 6
        self.text(bx0, by1 - 4, tr("keys 1–5 open the chapters · t changes the ink · "
                                   "a turns the animation on and off"),
                  self.f_small, "sw", width=bx1 - bx0)

    def draw_list_page(self, s):
        P = self.ink()
        _, key, page = s
        bx0, by0, bx1, by1 = self.page_box("left")
        title = tr(dict(BOOK_CHAPTERS)[key])
        items = self.page_items()
        self.sel = max(0, min(self.sel, len(items) - 1))
        self.text(bx0, by0, title.upper(), self.f_small)
        nums = [o.get("reg_n") for _, o in items if o.get("reg_n")]
        if key == "register" and nums:
            self.text(bx1, by0, f"nº {nums[0]}–{nums[-1]}", self.f_small, "ne")
        else:
            total = len(self.chapters[key])
            a = page * self.per + 1
            self.text(bx1, by0, tr("{a}–{b} of {n}", a=a, b=a + len(items) - 1, n=total),
                      self.f_small, "ne")
        self.rule(bx0, bx1, by0 + 18, double=True)
        cols = int((bx1 - bx0) // self.cw)
        tags = KIND_TAG if cols >= 42 else KIND_SHORT      # narrow page: short label
        y = by0 + 32
        self.rows_y = []
        for i, (kind, o) in enumerate(items):
            n = o.get("reg_n")
            num = f"{n:>5}" if n else "    —"
            if kind == "x":
                tag = tr("cancel.") if tags is KIND_TAG else "×"
                name = o.get("name", "")
            else:
                rk = kind_of(o)
                tag = tr(tags.get(rk, rk))
                name = label_any(o, self.data)
            room = cols - len(num) - len(tag) - 4
            name = " ".join(name.split())
            name = name if len(name) <= room else name[:room - 1] + "…"
            dots = "." * max(1, room - len(name))
            line = f"{num}  {name} {dots} {tag}"
            top = y - 3
            if i == self.sel:
                self.cv.create_rectangle(bx0 - 4, top, bx1 + 4, top + self.lh - 1,
                                         fill=P["ink"], outline="")
                self.text(bx0, y, line, fill=P["paper"])
            else:
                self.text(bx0, y, line)
                if kind == "x":
                    self.cv.create_line(bx0 + 7 * self.cw, y + self.lh / 2 - 3, bx1,
                                        y + self.lh / 2 - 3, fill=P["ink"])
            self.rows_y.append((top, top + self.lh, i))
            y += self.lh

    def draw_folio(self):
        """The right page: the chosen record, as much of it as fits."""
        P = self.ink()
        bx0, by0, bx1, by1 = self.page_box("right")
        items = self.page_items()
        if not items:
            return
        kind, o = items[min(self.sel, len(items) - 1)]
        n = o.get("reg_n")
        self.text(bx0, by0, f"Nº {n}" if n else tr("NO NUMBER"), self.f_small)
        if o.get("reg"):
            self.text(bx1, by0, stamp_label(o["reg"]), self.f_small, "ne")
        self.rule(bx0, bx1, by0 + 18, double=True)
        y = by0 + 30
        width = bx1 - bx0
        if kind == "x":
            self.text(bx0, y, tr("Cancelled"), self.f_title)
            y += 46
            for line in (tr("was: {name}", name=o.get("name", "")), f"id: {o.get('id', '')}",
                         tr("on: {at}", at=(o.get("at") or "").replace("T", " "))):
                self.text(bx0, y, line)
                y += self.lh
            for k in range(6):
                self.cv.create_line(bx0, by0 + 120 + k * 40, bx1, by0 + 80 + k * 40,
                                    fill=P["ink"], stipple="gray50")
            return
        rk = kind_of(o)
        kicker = tr(KIND_TAG.get(rk, rk)).upper()
        if rk == "form" and o.get("lang"):
            kicker += " · " + o["lang"]
        if rk == "source" and o.get("type"):
            kicker += " · " + o["type"]
        if rk == "metric":
            kicker = tr(HEALTH_TYPE_LABEL[htype(o)]).upper()
            if o.get("system"):
                kicker += " · " + system_label(o["system"])
        self.text(bx0, y, kicker, self.f_small)
        y += 18
        t = self.text(bx0, y, label_any(o, self.data), self.f_title, width=width)
        y = self.cv.bbox(t)[3] + 10
        self.rule(bx0, bx1, y)
        y += 12
        cols = max(10, int(width // self.cw))
        bottom = by1 - 6
        blocks = self.folio_blocks(o, rk)
        for head, body in blocks:
            if y > bottom - 2 * self.lh:
                break
            if head:
                self.text(bx0, y, head.upper(), self.f_small)
                y += 16
            lines = []
            for para in (body or "").splitlines() or [""]:
                lines += textwrap.wrap(para, cols) or [""]
            room = int((bottom - y) // (self.lh - 4))
            if len(lines) > room:
                lines = lines[:max(0, room - 1)] + [tr("… (continued on the card)")]
            for line in lines:
                self.text(bx0, y, line)
                y += self.lh - 4
            y += 10

    def folio_blocks(self, o, rk):
        d = self.data
        out = []
        if rk == "concept":
            out.append((tr("gloss"), o.get("gloss")))
        if rk == "form":
            bits = [o.get("roman"), o.get("attested"), o.get("status")]
            out.append((tr("form"), "  ·  ".join(b for b in bits if b)))
        if rk == "person":
            bits = [", ".join(o.get("tags", [])), o.get("place") or "",
                    tr("since {date}", date=o["met"]) if o.get("met") else ""]
            out.append(("", "  ·  ".join(b for b in bits if b)))
            live = open_tasks(o)
            if live:
                out.append((tr("tasks"), "\n".join(
                    f"[{MARK_OF.get(t.get('state'), ' ')}] {t.get('text', '')}"
                    for t in live[:5])))
            out.append((tr("notes"), o.get("notes_raw")))
        if rk == "source":
            out.append((tr("citation (ABNT)"), cite(o, "abnt", d)))
            users = [r for c in ("people", "entries", "corpus") for r in d[c]
                     if r.get("source") == o["id"]]
            if users:
                out.append((tr("source of {n}", n=len(users)),
                            ", ".join(label_any(r, d) for r in users[:12])))
        if rk == "metric" and htype(o) != "measure":
            out.append(("", "  ·  ".join(health_facts(o, d))))
            if o.get("sessions"):
                out.append((tr("sessions"), "\n".join(
                    f"{x.get('date', '')}  {x.get('text', '')}" for x in o["sessions"][-8:])))
        if rk == "metric" and htype(o) == "measure":
            ref = " – ".join(str(x) for x in (o.get("ref_low"), o.get("ref_high")) if x)
            out.append(("", f"{o.get('unit', '')}" + ("  ·  " + tr("reference: ") + ref if ref else "")))
            reads = o.get("readings", [])[-8:]
            if reads:
                out.append((tr("readings"), "\n".join(
                    f"{r.get('date', '')}  {r.get('value', '')}"
                    + ("  (!)" if out_of_range(o, r) else "") for r in reads)))
        if o.get("source") and rk != "source":
            out.append((tr("source"), resolve_source(o["source"], d)[1]))
        if rk in ("concept", "form", "metric"):
            out.append((tr("notes"), o.get("notes")))
        outs = [f"{rel_label(a['rel'])} → {label_any(self.idx[a['to']], d)}"
                for a in edges_from(d, o["id"]) if a["to"] in self.idx]
        ins = [f"{label_any(self.idx[a['from']], d)} → {rel_label(a['rel'])}"
               for a in edges_to(d, o["id"]) if a["from"] in self.idx]
        if outs:
            out.append((tr("links"), "\n".join(outs)))
        if ins:
            out.append((tr("cited by"), "\n".join(ins)))
        return [(h, b) for h, b in out if (b or "").strip()]

    def draw_footer(self):
        x0, y0, x1, y1 = self.book
        n = self.cur * 2 + 1
        self.text(x0 + self.pad, y1 - 10, str(n), self.f_small, "sw")
        self.text(x1 - self.pad, y1 - 10, str(n + 1), self.f_small, "se")
        card = tr("Enter: open on the card · ") if self.on_open else ""
        hint = (tr("PageUp / PageDown, ← →, wheel: turn · ↑ ↓: roll · 1–5: chapters · ")
                + card + tr("t: ink · a: animation · Esc: close · read-only"))
        if self.f_small.measure(hint) > self.W - 20:
            hint = (tr("PgUp/PgDn ← → wheel · ↑ ↓ · 1–5 · ") + ("Enter · " if card else "")
                    + tr("t · a · Esc · read-only"))
        self.text(self.W / 2, self.H - 6, hint, self.f_small, "s", fill=self.ink()["hint"])

    # ---------------------------------------------------------- virar
    def turn(self, delta, sel=None):
        target = self.cur + delta
        if self.busy or not 0 <= target < len(self.spreads):
            return "break"
        self.open_spread(target, delta, sel)
        return "break"

    def open_spread(self, target, delta, sel=None):
        if self.busy:
            return "break"
        self.cur = target
        n = len(self.page_items())
        self.sel = 0 if sel is None else max(0, min(n - 1, sel))
        if self.animate and delta:
            self.page_turn(1 if delta > 0 else -1)
        else:
            self.draw()
        return "break"

    def page_turn(self, direction):
        """The leaf turns: draws the new spread underneath and passes a blank
        leaf over it that folds at the spine, with its back in halftone and
        the shadow it casts."""
        self.busy = True
        self.draw()
        P = self.ink()
        shadow = self.cv.create_polygon(0, 0, 0, 0, fill=P["ink"], stipple="gray25",
                                        outline="")
        leaf = self.cv.create_polygon(0, 0, 0, 0, fill=P["paper"], outline=P["ink"])
        back = self.cv.create_polygon(0, 0, 0, 0, fill=P["ink"], stipple="gray12",
                                      outline="")
        parts = (leaf, back, shadow)

        def frame(k):
            self.leaf_at(parts, k / self.TURN_FRAMES, direction)
            if k < self.TURN_FRAMES:
                self._job = self.root.after(self.TURN_MS, frame, k + 1)
            else:
                self.cv.delete(*parts)
                self.busy = False

        frame(0)

    def leaf_at(self, parts, t, direction):
        """The leaf at instant t (0 to 1): held at the spine, its free edge goes
        from one side to the other; halfway it lifts, and its back shows."""
        leaf, back, shadow = parts
        x0, y0, x1, y1 = self.book
        pw = self.spine - x0
        lift = (y1 - y0) * 0.035
        c, s = math.cos(math.pi * t), math.sin(math.pi * t)
        reach = self.spine + direction * c * pw
        up = lift * s
        pts = (self.spine, y0, reach, y0 - up, reach, y1 + up, self.spine, y1)
        self.cv.coords(leaf, *pts)
        self.cv.coords(back, *(pts if t > 0.5 else (0,) * 8))
        sx = reach + direction * (-1 if t < 0.5 else 1) * 18 * s
        self.cv.coords(shadow, reach, y0, sx, y0, sx, y1, reach, y1)

    def step(self, delta):
        if self.busy:
            return "break"
        n = len(self.page_items())
        if not n:
            return self.turn(delta)
        i = self.sel + delta
        if i < 0:
            return self.turn(-1, sel=10 ** 6)
        if i >= n:
            return self.turn(1, sel=0)
        self.sel = i
        self.draw()
        return "break"

    def open_chapter(self, key):
        first = next(i for i, s in enumerate(self.spreads) if s[0] == "list" and s[1] == key)
        return self.open_spread(first, first - self.cur)

    def click(self, e):
        if self.busy:
            return
        for item in self.cv.find_overlapping(e.x - 1, e.y - 1, e.x + 1, e.y + 1):
            for tag in self.cv.gettags(item):
                if tag.startswith("toc:"):
                    self.open_chapter(tag[4:])
                    return
        s = self.spreads[self.cur]
        bx0, _, bx1, _ = self.page_box("left")
        if s[0] == "list" and bx0 - 6 <= e.x <= bx1 + 6:
            for top, bot, i in getattr(self, "rows_y", []):
                if top <= e.y < bot:
                    self.sel = i
                    self.draw()
                    return
        x0, _, x1, _ = self.book
        if self.spine < e.x <= x1:
            self.turn(1)
        elif x0 <= e.x < self.spine and s[0] == "front":
            self.turn(-1)

    def open_in_card(self):
        """Takes the main window to the chosen record (the logbook only reads)."""
        if not self.on_open or self.busy:
            return "break"
        items = self.page_items()
        if items:
            kind, o = items[min(self.sel, len(items) - 1)]
            if kind == "r":
                self.on_open(o["id"])
        return "break"

    def copy_id(self):
        items = self.page_items()
        if not items:
            return "break"
        kind, o = items[min(self.sel, len(items) - 1)]
        text = o.get("id", "") if kind == "r" else f"nº {o.get('reg_n')}"
        self.root.clipboard_clear()
        self.root.clipboard_append(text)
        self.root.title(tr("Copied: {value}", value=text))
        self.root.after(2500, lambda: self.root.title(tr("Kustos · logbook (read-only)")))
        return "break"

    def cycle_palette(self):
        names = list(BOOK_PALETTES)
        self.pal_name = names[(names.index(self.pal_name) + 1) % len(names)]
        self.draw()

    def toggle_animation(self):
        self.animate = not self.animate
        self.draw()

    def resized(self, _e=None):
        if self._job and not self.busy:
            try:
                self.root.after_cancel(self._job)
            except tk.TclError:
                pass
        self._job = self.root.after(80, self.relayout)

    def relayout(self):
        self._job = None
        if self.busy:
            return
        self.paginate()
        self.draw()


def set_window_icon(root):
    """kustos.ico next to the program, if present, for every window (title bar
    and taskbar); otherwise Tk's own icon stays."""
    icon = BASE / "kustos.ico"
    if icon.exists() and sys.platform == "win32":
        try:
            root.iconbitmap(default=str(icon))
        except tk.TclError:
            pass


def cmd_book():
    """Opens the base as a logbook, for reading only."""
    global tk, tkfont, ttk
    try:
        import tkinter as _tk
        from tkinter import font as _tkfont, ttk as _ttk
    except ImportError:
        raise SystemExit(tr("This Python came without Tkinter. Reinstall it with tcl/tk."))
    tk, tkfont, ttk = _tk, _tkfont, _ttk
    data = load_json()
    if needs_upgrade(data):
        print(tr("The base has no register numbers yet: open the main program once "
                 "first (the logbook writes nothing)."))
    root = tk.Tk()
    set_window_icon(root)
    BookView(root, data)
    root.mainloop()
    return 0


# ================================================================ app

def cmd_app(open_id=None):
    global tk, tkfont, ttk
    try:
        import tkinter as _tk
        from tkinter import font as _tkfont, ttk as _ttk
    except ImportError:
        raise SystemExit(tr("This Python came without Tkinter. Reinstall it with tcl/tk."))
    tk, tkfont, ttk = _tk, _tkfont, _ttk

    notices = []
    if JSON_FILE.exists() and needs_upgrade(load_json()):
        old = load_json()
        n_before = len(old.get("sources", []))
        opening = cmd_upgrade(quiet=True)
        n_after = len(load_json()["sources"])
        if schema_version(old) < 3:
            notices.append(tr("Base updated to {schema}: {n} source(s) created from the "
                              "SOURCE field.", schema=SCHEMA, n=n_after - n_before))
        if opening:
            notices.append(opening)
    if (CORPUS_SUBJECT and JSON_FILE.exists()
            and not (load_json().get("ui") or {}).get("corpus_subject")):
        save_ui({"corpus_subject": CORPUS_SUBJECT})
    reports = absorb_conflicts()
    if reports:
        notices.append(tr("Conflicts merged: ") + describe_merge(reports))
        try:
            write_mirror(load_json())
        except SystemExit:
            pass
    for o in other_locks():
        notices.append(tr("Also open on {host} since {since}: editing on both machines "
                          "at once causes conflicts.", host=o.get("host"), since=o.get("since")))
    take_lock()

    theme = (load_json().get("ui") or {}).get("theme", "paper")
    first = open_id
    try:
        while True:
            load_palette(theme)
            root = tk.Tk()
            set_window_icon(root)
            ui = App(root, theme, notices)
            notices = []
            if first:
                def jump(u=ui, rid=first):
                    try:
                        if rid in by_id(u.data):
                            u.open_record(rid)
                        else:
                            u.say(tr("The record {id} does not exist.", id=rid))
                    except Exception:
                        pass
                root.after(260, jump)
                first = None
            root.protocol("WM_DELETE_WINDOW", ui.on_close)
            root.mainloop()
            if not ui.restart_theme:
                break
            theme = ui.restart_theme
    finally:
        drop_lock()
    return 0


def main():
    if JSON_FILE.exists():
        set_lang(((read_vault(JSON_FILE) or {}).get("ui") or {}).get("lang", "en"))
    args = sys.argv[1:]
    if not args:
        return cmd_app()
    cmd, rest = args[0], args[1:]
    if cmd == "app":
        return cmd_app(rest[0] if rest else None)
    if cmd in ("logbook", "livro"):       # "livro" kept for older shortcuts
        return cmd_book()
    if cmd == "migrate":
        return cmd_migrate()
    if cmd == "merge":
        return cmd_merge()
    if cmd == "doctor":
        return cmd_doctor()
    if cmd == "mirror":
        cmd_mirror()
        write_corpus_html(load_json())
        return 0
    if cmd == "corpus":
        return cmd_corpus(open_it="--no-open" not in rest)
    if cmd == "health":
        return cmd_health(open_it="--no-open" not in rest)
    if cmd == "search" and rest:
        return cmd_search(" ".join(rest))
    if cmd == "history" and rest:
        return cmd_history(rest[0])
    if cmd == "replay":
        return cmd_replay()
    if cmd == "import" and rest:
        if rest[0] == "zotero" and len(rest) > 1:
            return cmd_import_zotero(rest[1])
        return cmd_import(rest[0])
    if cmd == "normalize":
        return cmd_normalize()
    if cmd == "upgrade":
        cmd_upgrade()
        return 0
    if cmd == "cite" and rest:
        return cmd_cite(rest[0], rest[1] if len(rest) > 1 else "abnt")
    if cmd == "export":
        return cmd_export(rest[0] if rest else "bibtex", rest[1] if len(rest) > 1 else None)
    print(__doc__)
    return 0


